window.TARBIYA={"pillars":[{"id":"iman","ic":"🌱","name":"التربية الإيمانية","desc":"غرس محبة الله وتعظيمه ومراقبته في القلب منذ الصغر، فهي الأساس الذي يقوم عليه كل خلق وعبادة.","items":[{"t":"ابدأ بالمحبة والرجاء قبل الخوف","d":"عرّف الطفل بربه من خلال نعمه عليه: من خلقك؟ من رزقك؟ من يحفظك؟ واجعل أول ما يعرفه عن الله رحمته وكرمه، ثم علّمه المراقبة برفق.","ev":[{"t":"﴿يا بني إنها إن تك مثقال حبة من خردل فتكن في صخرة أو في السماوات أو في الأرض يأت بها الله﴾","ref":"31:16","id":"quran:31:16"}]},{"t":"علّمه التوحيد بكلمات يفهمها","d":"كان النبي ﷺ يعلّم الصغار العقيدة بعبارات قصيرة واضحة يسهل حفظها.","ev":[{"t":"«يا غلام، إني أعلمك كلمات: احفظ الله يحفظك، احفظ الله تجده تجاهك، إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله»","ref":"رواه الترمذي وقال: حسن صحيح","id":"tirmidhi:2516"}]},{"t":"الوصية بالتوحيد قبل كل شيء","d":"أول وصايا لقمان لابنه النهي عن الشرك، وكان ذلك بأسلوب الشفقة: «يا بنيّ».","ev":[{"t":"﴿وإذ قال لقمان لابنه وهو يعظه يا بني لا تشرك بالله إن الشرك لظلم عظيم﴾","ref":"31:13","id":"quran:31:13"}]},{"t":"الفطرة تحتاج إلى من يحفظها","d":"يولد الطفل على الفطرة، والوالدان والبيئة هم الذين يحفظونها أو يغيّرونها؛ فالتربية مسؤولية.","ev":[{"t":"«كل مولود يولد على الفطرة، فأبواه يهودانه أو ينصرانه أو يمجسانه»","ref":"متفق عليه","id":"bukhari:1385"}]},{"t":"القرآن رفيق الطفولة","d":"أسمِعه القرآن، وحفّظه قصار السور، واربطه بمعانيها بقصص قصيرة.","ev":[{"t":"«خيركم من تعلّم القرآن وعلّمه»","ref":"رواه البخاري","id":"bukhari:5027"}]},{"t":"اربطه بالنبي ﷺ محبةً واقتداءً","d":"احكِ له من سيرته وشمائله ما يناسب سنه، فالمحبة تقود إلى الاتباع.","ev":[{"t":"«لا يؤمن أحدكم حتى أكون أحب إليه من والده وولده والناس أجمعين»","ref":"متفق عليه","id":"bukhari:14"}]}]},{"id":"ibada","ic":"🕌","name":"التربية على العبادة","desc":"تدريب الطفل على العبادات بالتدرج قبل سن التكليف، حتى يبلغ وقد صارت العبادة عادة محبوبة.","items":[{"t":"الصلاة: من السابعة تدريباً، ومن العاشرة حزماً","d":"ثلاث سنوات من التدريب بالتحفيز والقدوة، والحزم بعد العاشرة تأديب لا إيذاء فيه.","ev":[{"t":"«مُروا أولادكم بالصلاة وهم أبناء سبع سنين، واضربوهم عليها وهم أبناء عشر، وفرّقوا بينهم في المضاجع»","ref":"رواه أبو داود، وحسّنه الألباني","id":"abudawud:495"}]},{"t":"الصيام تدريباً","d":"كان الصحابة يصوّمون صغارهم ويشغلونهم باللعب حتى الإفطار.","ev":[{"t":"قالت الرُّبيّع بنت معوّذ: «فكنا نصومه بعدُ، ونصوّم صبياننا، ونجعل لهم اللعبة من العهن، فإذا بكى أحدهم على الطعام أعطيناه ذاك حتى يكون عند الإفطار»","ref":"متفق عليه","id":"bukhari:1960"}]},{"t":"أمر الأهل بالصلاة والصبر عليه","d":"التربية على العبادة تحتاج إلى نفس طويل وتكرار بلا ملل.","ev":[{"t":"﴿وأمر أهلك بالصلاة واصطبر عليها﴾","ref":"20:132","id":"quran:20:132"}]},{"t":"الحج والعمرة بالصغار","d":"للصغير حج يؤجر عليه، ولمن حجّ به أجر.","ev":[{"t":"رفعت امرأة صبياً فقالت: ألهذا حج؟ قال: «نعم، ولكِ أجر»","ref":"رواه مسلم","id":"muslim:3253"}]}]},{"id":"akhlaq","ic":"🌷","name":"التربية الأخلاقية","desc":"الأخلاق تُكتسب بالقدوة والتدريب والتشجيع، وهي أثقل ما في الميزان.","items":[{"t":"الصدق حتى في المزاح والوعد","d":"لا تكذب على طفلك ولو لتسكيته، فالطفل يتعلم الصدق من صدقك معه.","ev":[{"t":"قال ﷺ لأم دعته لتعطي ابنها شيئاً: «وما أردتِ أن تعطيه؟» قالت: تمراً، قال: «أما إنك لو لم تعطيه شيئاً كُتبت عليك كذبة»","ref":"رواه أبو داود","id":"abudawud:4991"}]},{"t":"آداب الطعام بالتعليم الرفيق","d":"علّم الأدب في موقفه بكلمات قليلة وبلا تعنيف.","ev":[{"t":"«يا غلام، سمِّ الله، وكُل بيمينك، وكُل مما يليك»","ref":"متفق عليه","id":"bukhari:5376"}]},{"t":"خُلُق حسن هو الغاية","d":"حسن الخلق أثقل ما في الميزان، فاجعله معيار نجاح التربية لا الدرجات وحدها.","ev":[{"t":"«ما شيء أثقل في ميزان المؤمن يوم القيامة من خلق حسن»","ref":"رواه الترمذي وقال: حسن صحيح","id":"tirmidhi:2002"}]},{"t":"الاستئذان واحترام الخصوصية","d":"علّم الطفل الاستئذان في أوقات الخلوة الثلاثة، وعند البلوغ في كل وقت.","ev":[{"t":"﴿يا أيها الذين آمنوا ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات﴾","ref":"24:58","id":"quran:24:58"},{"t":"﴿وإذا بلغ الأطفال منكم الحلم فليستأذنوا كما استأذن الذين من قبلهم﴾","ref":"24:59","id":"quran:24:59"}]},{"t":"وصايا لقمان منهج متكامل","d":"الصلاة، والأمر بالمعروف، والصبر، والتواضع، وخفض الصوت.","ev":[{"t":"﴿يا بني أقم الصلاة وأمر بالمعروف وانه عن المنكر واصبر على ما أصابك﴾","ref":"31:17","id":"quran:31:17"},{"t":"﴿ولا تصعر خدك للناس ولا تمش في الأرض مرحًا﴾","ref":"31:18","id":"quran:31:18"},{"t":"﴿واقصد في مشيك واغضض من صوتك﴾","ref":"31:19","id":"quran:31:19"}]},{"t":"الحياء خلق الإسلام","d":"علّمه الحياء من الله ومن الناس، فالحياء لا يأتي إلا بخير.","ev":[{"t":"«الحياء لا يأتي إلا بخير»","ref":"متفق عليه","id":"bukhari:6117"}]},{"t":"الأمانة وحفظ السر","d":"كان أنس صغيراً فاستأمنه النبي ﷺ على سرّ فحفظه.","ev":[{"t":"أسرّ النبي ﷺ إلى أنس بسرّ، فسألته أمه فقال: إنها حاجة، قالت: «لا تحدثن بسر رسول الله ﷺ أحداً»","ref":"رواه مسلم","id":"muslim:6378"}]}]},{"id":"nafs","ic":"💛","name":"التربية النفسية والعاطفية","desc":"الطفل الذي يشبع حباً وأماناً يكون أقدر على الطاعة والثقة والنجاح.","items":[{"t":"التقبيل والرحمة سنة","d":"إظهار الحب للأولاد بالقبلة والضم من هدي النبي ﷺ، وليس تدليلاً مذموماً.","ev":[{"t":"قبّل النبي ﷺ الحسن بن علي، فقال الأقرع بن حابس: إن لي عشرة من الولد ما قبّلت منهم أحداً، فقال ﷺ: «من لا يَرحم لا يُرحم»","ref":"متفق عليه","id":"bukhari:5997"}]},{"t":"الرفق في كل شيء","d":"الرفق يزيّن التربية، والعنف يفسدها.","ev":[{"t":"«إن الرفق لا يكون في شيء إلا زانه، ولا يُنزع من شيء إلا شانه»","ref":"رواه مسلم","id":"muslim:6602"}]},{"t":"لا تُكثر اللوم","d":"خدم أنس النبيَّ ﷺ عشر سنين فما عاتبه على شيء فعله أو تركه.","ev":[{"t":"قال أنس: «خدمت النبي ﷺ عشر سنين، فما قال لي: أفٍّ، ولا: لمَ صنعت؟ ولا: ألا صنعت؟»","ref":"متفق عليه","id":"bukhari:6038"}]},{"t":"الملاعبة والمداعبة","d":"مشاركة الطفل لعبه واهتماماته تفتح قلبه لك.","ev":[{"t":"كان ﷺ يمازح أخاً صغيراً لأنس فيقول: «يا أبا عُمير، ما فعل النُّغَير؟»","ref":"متفق عليه","id":"bukhari:6129"}]},{"t":"العدل بين الأولاد","d":"التفضيل يورث الحسد والعقوق.","ev":[{"t":"«فاتقوا الله واعدلوا بين أولادكم»","ref":"متفق عليه","id":"bukhari:2587"}]},{"t":"الإصغاء لمشاعره","d":"أعطه حق التعبير عن حزنه وغضبه بالكلام، ثم وجّهه.","ev":[{"t":"«إن العين تدمع، والقلب يحزن، ولا نقول إلا ما يرضي ربنا»","ref":"متفق عليه","id":"bukhari:1303"}]}]},{"id":"aql","ic":"🧠","name":"التربية العقلية والعلمية","desc":"تنمية التفكير وحب العلم، وتعليم الطفل كيف يسأل ويبحث ويتعلّم.","items":[{"t":"العلم طريق إلى الجنة","d":"اربط طلب العلم بالأجر لا بالدرجات وحدها.","ev":[{"t":"«من سلك طريقاً يلتمس فيه علماً سهّل الله له به طريقاً إلى الجنة»","ref":"رواه مسلم","id":"muslim:6853"}]},{"t":"السؤال والحوار تعليم","d":"كان النبي ﷺ يطرح الأسئلة على أصحابه ليشحذ تفكيرهم.","ev":[{"t":"«إن من الشجر شجرة لا يسقط ورقها، وإنها مثل المسلم، فحدّثوني ما هي؟»","ref":"متفق عليه","id":"bukhari:61"}]},{"t":"التفكر في خلق الله","d":"اخرج بطفلك إلى الطبيعة واسأله عن آيات الله فيها.","ev":[{"t":"﴿إن في خلق السماوات والأرض واختلاف الليل والنهار لآيات لأولي الألباب﴾","ref":"3:190","id":"quran:3:190"}]},{"t":"القراءة عادة يومية","d":"خصص ربع ساعة للقراءة المشتركة، وابنِ مكتبة صغيرة في البيت.","ev":[{"t":"﴿اقرأ باسم ربك الذي خلق﴾","ref":"96:1","id":"quran:96:1"}]}]},{"id":"jism","ic":"💪","name":"التربية الجسمية والصحية","desc":"البدن أمانة، والقوة محبوبة إلى الله، فعلّمه الرياضة والنظافة والتغذية السليمة.","items":[{"t":"المؤمن القوي","d":"شجّع الرياضة النافعة: السباحة، والجري، والرماية، والفروسية.","ev":[{"t":"«المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف، وفي كلٍّ خير»","ref":"رواه مسلم","id":"muslim:6774"}]},{"t":"الرمي والتدريب","d":"حثّ النبي ﷺ على تعلّم الرمي.","ev":[{"t":"«ارموا بني إسماعيل، فإن أباكم كان رامياً»","ref":"رواه البخاري","id":"bukhari:2899"}]},{"t":"سنن الفطرة والنظافة","d":"علّمه النظافة الشخصية وسنن الفطرة بالتدريج.","ev":[{"t":"«الفطرة خمس: الختان، والاستحداد، وقص الشارب، وتقليم الأظفار، ونتف الآباط»","ref":"متفق عليه","id":"bukhari:5889"}]},{"t":"الاعتدال في الطعام","d":"علّمه ألا يملأ بطنه، وأن يأكل مما ينفعه.","ev":[{"t":"«ما ملأ آدميٌّ وعاءً شراً من بطن، بحسب ابن آدم أكلات يُقمن صلبه»","ref":"رواه الترمذي وقال: حسن صحيح","id":"tirmidhi:2380"}]}]},{"id":"ijtima","ic":"🤝","name":"التربية الاجتماعية","desc":"تعليم الطفل حقوق الناس: الوالدين، والأرحام، والجيران، والأصدقاء، والكبير والصغير.","items":[{"t":"رحمة الصغير وتوقير الكبير","d":"أدب التعامل مع الناس جزء من الدين.","ev":[{"t":"«ليس منا من لم يرحم صغيرنا ويوقّر كبيرنا»","ref":"رواه الترمذي","id":"tirmidhi:1919"}]},{"t":"السلام على الصبيان","d":"سلّم على الأطفال ليتعلموا السلام بالقدوة.","ev":[{"t":"أن أنساً مرّ على صبيان فسلّم عليهم، وقال: «كان النبي ﷺ يفعله»","ref":"متفق عليه","id":"bukhari:6247"}]},{"t":"اختيار الصحبة","d":"الصديق مرآة، فاعرف أصحاب ولدك وأهلهم.","ev":[{"t":"«المرء على دين خليله، فلينظر أحدكم من يخالل»","ref":"رواه أبو داود والترمذي","id":"abudawud:4833"}]},{"t":"الكلمة الطيبة والإصلاح","d":"علّمه حل الخلاف بالكلمة الطيبة والاعتذار.","ev":[{"t":"﴿وقل لعبادي يقولوا التي هي أحسن إن الشيطان ينزغ بينهم﴾","ref":"17:53","id":"quran:17:53"}]},{"t":"صلة الرحم","d":"خذه معك لزيارة الأقارب، وعلّمه أن الصلة تبسط الرزق وتطيل العمر.","ev":[{"t":"«من أحب أن يُبسط له في رزقه، ويُنسأ له في أثره، فليصل رحمه»","ref":"متفق عليه","id":"bukhari:5986"}]},{"t":"الإحسان إلى الجار","d":"علّمه ألا يؤذي الجيران بالصوت واللعب.","ev":[{"t":"«من كان يؤمن بالله واليوم الآخر فلا يؤذِ جاره»","ref":"متفق عليه","id":"bukhari:6018"}]}]},{"id":"iffa","ic":"🛡️","name":"التربية على العفة","desc":"تهيئة الولد والبنت للبلوغ بعلم وحياء، وحمايتهما من المخاطر، بأسلوب هادئ مناسب للسن.","items":[{"t":"التفريق في المضاجع","d":"من سن العاشرة يُفرق بين الأولاد في النوم.","ev":[{"t":"«وفرّقوا بينهم في المضاجع»","ref":"رواه أبو داود","id":"abudawud:495"}]},{"t":"غض البصر للجنسين","d":"علّم أولادك غض البصر، وراقب ما يصل إليهم عبر الشاشات.","ev":[{"t":"﴿قل للمؤمنين يغضوا من أبصارهم ويحفظوا فروجهم ذلك أزكى لهم﴾","ref":"24:30","id":"quran:24:30"},{"t":"﴿وقل للمؤمنات يغضضن من أبصارهن ويحفظن فروجهن﴾","ref":"24:31","id":"quran:24:31"}]},{"t":"الحوار لا الزجر","d":"حين جاء شاب يستأذن في الزنا حاوره النبي ﷺ ودعا له، ولم يعنّفه.","ev":[{"t":"«أتحبه لأمك؟» قال: لا والله... ثم وضع يده عليه وقال: «اللهم اغفر ذنبه، وطهّر قلبه، وحصّن فرجه»","ref":"رواه أحمد، وصححه الألباني","id":"ahmad:21185"}]},{"t":"الشباب والزواج","d":"وجّه الشاب إلى الزواج عند القدرة، وإلى الصوم والانشغال النافع قبلها.","ev":[{"t":"«يا معشر الشباب، من استطاع منكم الباءة فليتزوج... ومن لم يستطع فعليه بالصوم فإنه له وِجاء»","ref":"متفق عليه","id":"bukhari:5065"}]}]},{"id":"mal","ic":"💰","name":"التربية المالية والعملية","desc":"تعليم الكسب الحلال، والادخار، والإنفاق، وتحمّل المسؤولية.","items":[{"t":"العمل باليد شرف","d":"علّمه أن الكسب الحلال عبادة، وأشركه في أعمال البيت.","ev":[{"t":"«ما أكل أحد طعاماً قط خيراً من أن يأكل من عمل يده»","ref":"رواه البخاري","id":"bukhari:2072"}]},{"t":"الاعتدال في الإنفاق","d":"لا إسراف ولا تقتير.","ev":[{"t":"﴿والذين إذا أنفقوا لم يسرفوا ولم يقتروا وكان بين ذلك قوامًا﴾","ref":"25:67","id":"quran:25:67"}]},{"t":"المسؤولية بالتدريج","d":"أعطه مصروفاً يديره، ومهمة يتحملها، فالراعي مسؤول عن رعيته.","ev":[{"t":"«كلكم راعٍ، وكلكم مسؤول عن رعيته»","ref":"متفق عليه","id":"bukhari:893"}]}]}],"methods":[{"t":"القدوة","d":"أقوى وسائل التربية؛ فالطفل يقلّد ما يرى قبل أن يفهم ما يسمع.","ev":[{"t":"﴿لقد كان لكم في رسول الله أسوة حسنة﴾","ref":"33:21","id":"quran:33:21"},{"t":"﴿يا أيها الذين آمنوا لم تقولون ما لا تفعلون﴾","ref":"61:2","id":"quran:61:2"}]},{"t":"الموعظة الرفيقة","d":"موعظة قصيرة في وقت مناسب، بأسلوب الشفقة كما في «يا بنيّ».","ev":[{"t":"﴿وإذ قال لقمان لابنه وهو يعظه يا بني﴾","ref":"31:13","id":"quran:31:13"}]},{"t":"القصة","d":"قصص القرآن والأنبياء والصحابة تغرس القيم دون أوامر مباشرة.","ev":[{"t":"﴿لقد كان في قصصهم عبرة لأولي الألباب﴾","ref":"12:111","id":"quran:12:111"}]},{"t":"الحوار والإقناع","d":"حاور ابنك واسمع حجته، كما حاور إبراهيم ابنه في أعظم أمر.","ev":[{"t":"﴿يا بني إني أرى في المنام أني أذبحك فانظر ماذا ترى﴾","ref":"37:102","id":"quran:37:102"}]},{"t":"التدرج والعادة","d":"الخير عادة؛ فدرّبه على العبادة والخلق خطوة خطوة حتى تصير طبعاً.","ev":[{"t":"«أحب الأعمال إلى الله أدومها وإن قلّ»","ref":"متفق عليه","id":"bukhari:6464"}]},{"t":"التشجيع والمكافأة","d":"امدح الفعل الحسن وكافئ عليه، فقد كان النبي ﷺ يثني على أصحابه.","ev":[{"t":"«نِعم الرجل عبد الله لو كان يصلي من الليل»","ref":"متفق عليه","id":"bukhari:1158"}]},{"t":"الحزم بلا قسوة","d":"العقوبة آخر الوسائل، تكون بقدر الخطأ، بلا إهانة ولا ضرب للوجه.","ev":[{"t":"«إذا قاتل أحدكم أخاه فليجتنب الوجه»","ref":"رواه مسلم","id":"muslim:6651"}]},{"t":"الدعاء للأولاد","d":"سلاح الوالدين الدائم، ولا تدعُ عليهم في الغضب.","ev":[{"t":"﴿ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إمامًا﴾","ref":"25:74","id":"quran:25:74"},{"t":"«لا تدعوا على أنفسكم، ولا تدعوا على أولادكم...»","ref":"رواه مسلم","id":"muslim:7512"}]}],"newborn":[{"t":"الأذان في أذن المولود والتحنيك","zad":"zad:251","ev":[{"t":"وُلد لأبي موسى غلام فأتى به النبي ﷺ «فسمّاه إبراهيم، فحنّكه بتمرة، ودعا له بالبركة»","ref":"متفق عليه","id":"bukhari:5467"}]},{"t":"العقيقة","zad":"zad:246","ev":[{"t":"«كل غلام رهينة بعقيقته، تُذبح عنه يوم سابعه، ويُحلق، ويُسمّى»","ref":"رواه أبو داود والترمذي وصححه","id":"abudawud:2837"}]},{"t":"التسمية والختان","zad":"zad:252","ev":[{"t":"«إن أحب أسمائكم إلى الله: عبد الله وعبد الرحمن»","ref":"رواه مسلم","id":"muslim:5587"}]},{"t":"اختيار الاسم الحسن","zad":"zad:254","ev":[]},{"t":"الرضاعة","zad":"","ev":[{"t":"﴿والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة﴾","ref":"2:233","id":"quran:2:233"}]}],"problems":[{"cat":"صغار","t":"نوبات الغضب والصراخ (التشنّج)","d":"يرمي الطفل نفسه أرضاً ويصرخ إذا مُنع من شيء.","sci":"الجزء المسؤول عن ضبط الانفعال في الدماغ (القشرة الأمامية) لا يكتمل إلا متأخراً، فالطفل بين ١ و٤ سنوات لا يملك بعد أدوات تهدئة نفسه، ويحتاج إلى «تهدئة مشتركة» من الكبير.","steps":["حافظ على هدوئك؛ أنت مرآة الطفل.","تأكد من سلامته، ولا تتفاوض أثناء النوبة.","سمِّ شعوره: «أنت غاضب لأنك تريد الحلوى».","لا تستجب للطلب بسبب الصراخ، وإلا تعلّم أن الصراخ ينجح.","بعد هدوئه: ضمّة، ثم علّمه كلمة يقولها بدل الصراخ.","قلّل المسببات: الجوع والنعاس والتعب."],"q":"الغضب","say":[["اسكت وإلا…","أنا معك، لما تهدأ نتكلم"]],"age":"١–٥"},{"cat":"صغار","t":"العض والضرب عند الصغار","d":"يعض أو يضرب أطفالاً آخرين أو والديه.","sci":"سلوك شائع قبل اكتمال اللغة؛ فالطفل يعبّر بجسده عما لا يستطيع قوله، أو يجرّب ردّة الفعل.","steps":["أوقفه فوراً بهدوء وحزم: «لا نعض، العض يؤلم».","التفت إلى المتضرر واهتم به أمامه، لا إلى المعتدي.","علّمه بديلاً: «قل: لا! أو تعال ناديني».","لا تعضّه أو تضربه لتعلّمه، فهذا يعلّمه العكس.","لاحظ متى يتكرر (تعب، ازدحام) وتجنّب تلك الظروف."],"q":"الرفق","say":[],"age":"١–٤"},{"cat":"صغار","t":"رفض الطعام وانتقائية الأكل","d":"يأكل أصنافاً محدودة ويرفض الجديد.","sci":"الخوف من الأطعمة الجديدة مرحلة طبيعية في النمو، وقد يحتاج الطفل أن يرى الصنف ويتذوقه ١٠–١٥ مرة قبل أن يقبله.","steps":["قدّم الصنف الجديد بكمية صغيرة بجانب طعام يحبه.","لا تُجبره ولا ترشُه بالحلوى ليأكل.","كلوا معاً على المائدة؛ القدوة أقوى من الأمر.","أشركه في التسوّق والتحضير.","حدّد أوقات الوجبات، وقلّل العصير والوجبات الخفيفة بينها.","راجع الطبيب إن كان وزنه أو نموه متأثراً."],"q":"الطعام","say":[["كُل وإلا ما في لعب","ذُق لقمة واحدة، وإن ما عجبك لا بأس"]],"age":"٢–٨"},{"cat":"صغار","t":"صعوبة النوم والاستيقاظ ليلاً","d":"يرفض النوم أو يستيقظ كثيراً ويأتي لغرفة والديه.","sci":"الروتين الثابت قبل النوم يساعد الجسم على إفراز هرمون النوم (الميلاتونين)، والشاشات قبل النوم تؤخره.","steps":["روتين ثابت كل ليلة: حمام، أسنان، أذكار النوم، قصة، ثم إطفاء.","وقت نوم ثابت حتى في الإجازات تقريباً.","لا شاشات قبل النوم بساعة.","إن استيقظ: أرجعه لسريره بهدوء وبأقل كلام.","نور خافت وصوت هادئ إن كان يخاف."],"q":"النوم","say":[],"age":"١–١٠"},{"cat":"صغار","t":"التدريب على استخدام الحمّام","d":"تأخر أو صعوبة في ترك الحفاض.","sci":"معظم الأطفال يكونون مستعدين بين ٢ و٣ سنوات، وعلامات الاستعداد أهم من العمر: البقاء جافاً ساعتين، والانزعاج من الحفاض، وفهم التعليمات.","steps":["ابدأ عند ظهور علامات الاستعداد لا بضغط الآخرين.","أوقات ثابتة: بعد الاستيقاظ والطعام.","امدح المحاولة، ولا تعاقب على الحوادث أبداً.","ملابس سهلة الخلع.","علّمه آداب الخلاء والدعاء تدريجياً.","إن تراجع بعد نجاح (كمولود جديد) فاصبر فهو مؤقت."],"q":"الطهارة","say":[],"age":"٢–٤"},{"cat":"صغار","t":"التبول الليلي","d":"يبلل فراشه ليلاً بعد سن الخامسة.","sci":"التبول الليلي شائع حتى سن ٥–٦ وله أسباب جسدية غالباً (نضج المثانة، والوراثة، والنوم العميق)، وليس كسلاً ولا عناداً.","steps":["لا تعاقب ولا تُخجله أمام إخوته.","قلّل الشرب قبل النوم بساعة، ودعه يدخل الحمام قبل النوم.","غطاء مقاوم للماء للفراش.","جدول نجوم لليالي الجافة.","استشر طبيب الأطفال بعد السادسة أو إن عاد فجأة بعد انقطاع."],"q":"الرفق","say":[],"age":"٥+"},{"cat":"صغار","t":"التعلق الشديد بالأم وقلق الانفصال","d":"يبكي بشدة عند ذهاب الأم أو دخول الروضة.","sci":"قلق الانفصال مرحلة طبيعية بين ٨ أشهر و٣ سنوات، ويخف كلما تعلّم الطفل أن أمه تذهب وتعود فعلاً.","steps":["ودّعه دائماً ولا تتسلل خفية؛ التسلل يزيد القلق.","وداع قصير ثابت: «أحبك، أرجع بعد العصر».","ابدأ بفترات غياب قصيرة ثم أطِلها.","عُد في الموعد الذي قلته.","غرض من البيت يحمله معه."],"q":"الرحمة","say":[["لو بكيت ما أرجع","سأرجع بعد النوم، وأنت بأمان هنا"]],"age":"١–٥"},{"cat":"صغار","t":"تأخر الكلام","d":"لا يتكلم كلمات كأقرانه.","sci":"الكلام يتطور بالتفاعل الحي: الحديث المباشر والقراءة المشتركة، والشاشات لا تعوّض ذلك بل ترتبط كثرتها بتأخر اللغة.","steps":["تحدّث معه طوال اليوم وصِف ما تفعل.","اقرأ له قصصاً مصورة يومياً.","قلّل الشاشات أو امنعها قبل سنتين.","لا تلبِّ طلبه بالإشارة فقط؛ شجّعه على الكلمة.","إن لم يقل كلمات مفيدة عند ١٨ شهراً أو جملتين قصيرتين عند سنتين: افحص السمع وراجع أخصائي التخاطب."],"q":"الكلام","say":[],"age":"١–٤"},{"cat":"سلوك","t":"العناد","d":"يرفض الأوامر ويقول «لا» دائماً.","sci":"العناد حاجة طبيعية لإثبات الذات والاستقلال، ويظهر بقوة بين ٢ و٤ سنوات وفي المراهقة. وكثرة الأوامر تزيده.","steps":["أعطه خيارين مقبولين بدل الأمر المباشر.","قلّل الأوامر واجعلها واضحة وقصيرة.","لا تدخل في صراع إرادات، وحافظ على هدوئك.","امدح كل تعاون مهما كان صغيراً."],"q":"الرفق","say":[["البس الآن!","تلبس القميص الأزرق أم الأحمر؟"]],"age":""},{"cat":"سلوك","t":"الكذب","d":"يكذب ليتجنّب العقاب أو ليحصل على شيء.","sci":"الكذب عند الصغير غالباً خوف من العقاب أو خيال واسع، وكلما اشتدت العقوبة على الاعتراف زاد الكذب.","steps":["كن قدوة في الصدق ولو في المزاح.","لا تعاقب بشدة على الاعتراف، بل اشكر الصدق.","فرّق بين خيال الطفل الصغير والكذب المقصود.","لا تسأل سؤالاً تعرف جوابه لتوقعه: قل «رأيتك فعلت كذا، كيف نصلحه؟».","احكِ قصصاً عن الصدق وثوابه."],"q":"الصدق","say":[["أنت كذاب!","أنا أقدّر لما تقول الحقيقة حتى لو كانت صعبة"]],"age":""},{"cat":"سلوك","t":"السرقة وأخذ أغراض الآخرين","d":"يأخذ أغراض إخوته أو زملائه دون إذن.","sci":"عند الصغار قبل ٦ سنوات لا يكتمل مفهوم الملكية بعد؛ أما بعدها فقد تكون رغبة أو تقليداً أو طلباً للاهتمام.","steps":["لا تصفه بالسارق.","علّمه مفهوم «هذا لي وهذا لغيري» واطلب الإذن.","أعِد الشيء معه لصاحبه واعتذرا.","ابحث عن السبب: حاجة؟ غيرة؟ ضغط أصدقاء؟","أعطه مصروفاً يدبّره."],"q":"الأمانة","say":[["يا حرامي","هذا ليس لنا، نرجعه ونعتذر معاً"]],"age":""},{"cat":"سلوك","t":"الألفاظ البذيئة والشتم","d":"يردد كلمات سيئة سمعها.","sci":"الطفل يقلّد ما يسمع، ويكرر الكلمة أكثر إذا لاحظ أنها تثير ردة فعل قوية.","steps":["لا تضحك ولا تنفعل؛ قل بهدوء: «هذه كلمة لا نقولها».","اعرف مصدرها: أصدقاء، شاشات، أقارب.","علّمه كلمات بديلة للتعبير عن الغضب.","كن قدوة في ألفاظك.","امدح الكلام الطيب."],"q":"اللسان","say":[],"age":""},{"cat":"سلوك","t":"الحركة الزائدة وقلة التركيز","d":"لا يستقر في مكان ولا يكمل مهمة.","sci":"كثير من الأطفال كثيرو الحركة طبيعياً، لكن إذا كانت الحركة والاندفاع وتشتت الانتباه شديدة ومستمرة في البيت والمدرسة معاً لأكثر من ٦ أشهر فقد يكون «فرط الحركة وتشتت الانتباه»، ويُشخّصه المختص فقط.","steps":["وفّر له وقتاً يومياً للحركة واللعب الحر.","قسّم المهام إلى خطوات قصيرة مع استراحات.","روتين ثابت وتعليمات قصيرة واحدة تلو الأخرى.","قلّل الشاشات والسكريات.","إن أثّر في دراسته وعلاقاته فراجع طبيب الأطفال أو الطبيب النفسي للأطفال، ولا تشخّصه بنفسك."],"q":"الصبر","say":[],"age":""},{"cat":"سلوك","t":"العدوانية وضرب الآخرين","d":"يضرب أصدقاءه أو إخوته عند الخلاف.","sci":"الطفل يتعلم العنف بالتقليد (من البيت أو الشاشات)، ويستعمله إذا لم يتعلم مهارات حل الخلاف.","steps":["أوقفه فوراً، وافصل بين الأطفال.","لا تضربه على الضرب.","علّمه تسمية مشاعره وطلب المساعدة.","تدرّبوا بالتمثيل على حل خلاف.","راقب الألعاب والمقاطع العنيفة.","كافئ اللعب الهادئ."],"q":"الغضب","say":[],"age":""},{"cat":"سلوك","t":"الأنانية وعدم المشاركة","d":"يرفض أن يشارك ألعابه.","sci":"قبل سن ٣–٤ سنوات لا يفهم الطفل المشاركة بعد، وتنمو مع العمر بالتدريب لا بالإجبار.","steps":["لا تجبره على إعطاء أغلى ألعابه؛ دعه يختار لعبة للمشاركة.","استخدم التناوب بالمؤقت.","امدح كل مشاركة.","كن قدوة في العطاء، وأشركه في الصدقة."],"q":"الإيثار","say":[],"age":""},{"cat":"سلوك","t":"عدم احترام الكبار والرد بوقاحة","d":"يرد على والديه أو معلميه بأسلوب غير لائق.","sci":"يزيد هذا السلوك إذا كان التعامل في البيت حاداً، أو إذا نجح الرد الوقح في الحصول على ما يريد.","steps":["حافظ على هدوئك ولا ترد بالمثل.","قل بحزم: «يمكنك أن تختلف معي باحترام».","لا تكمل الحديث حتى يتكلم بأدب.","كن قدوة في احترامه هو أيضاً.","علّمه «وقل لهما قولاً كريماً»."],"q":"بر الوالدين","say":[],"age":""},{"cat":"سلوك","t":"الفوضى وعدم ترتيب الغرفة","d":"يترك أغراضه مبعثرة.","sci":"الترتيب مهارة تُتعلّم بالتدريج والتكرار، ويحتاج الطفل خطوات واضحة لا أمراً عاماً.","steps":["قسّم المهمة: «الكتب على الرف، والملابس في السلة».","رتّبوا معاً في البداية.","صناديق ملصقة بصور لكل نوع.","روتين ترتيب ١٠ دقائق قبل النوم.","عاقبة منطقية: اللعبة غير المرتبة تُحفظ يوماً."],"q":"النظافة","say":[],"age":""},{"cat":"سلوك","t":"كثرة الطلبات والإلحاح على الشراء","d":"يلحّ في السوق ويبكي حتى يُشترى له.","sci":"إذا نجح الإلحاح مرة واحدة تعلّم الطفل أن يكرره؛ والاتفاق المسبق يقلل الصراع.","steps":["اتفق معه قبل الخروج على ما سيُشترى.","لا تشترِ بسبب البكاء.","قائمة أمنيات يكتب فيها ما يريد للمناسبات.","مصروف يدّخر منه لما يريد.","علّمه القناعة وشكر النعمة."],"q":"القناعة","say":[["خلاص خذ وسكت","اتفقنا اليوم على الخبز فقط، نكتبها في قائمة أمنياتك"]],"age":""},{"cat":"مشاعر","t":"الخوف والقلق","d":"يخاف من الظلام أو الوحدة أو أشياء معينة.","sci":"مخاوف الظلام والانفصال والحيوانات طبيعية في أعمار معينة، وتزيد بالسخرية أو التخويف.","steps":["لا تسخر من خوفه، واسمعه.","علّمه أذكار النوم والمعوذات ليشعر بالحماية.","واجه الخوف بالتدريج لا بالإجبار.","لا تخوّفه لتسكيته.","إن طال أو أعاق حياته فاستشر مختصاً."],"q":"المعوذات","say":[],"age":""},{"cat":"مشاعر","t":"الخجل والانطواء","d":"يرفض الكلام مع الناس ويختبئ خلف والديه.","sci":"الخجل طبع لا عيب، وكثير من الأطفال يحتاجون وقتاً للتأقلم. والضغط عليه أو وصفه بالخجول أمام الناس يرسّخه.","steps":["لا تصفه بـ«الخجول» أمام الآخرين.","أعطه وقتاً للتأقلم في المكان الجديد.","درّبه بالتمثيل على التحية والسلام.","لقاءات مع طفل واحد قبل المجموعات.","امدح كل خطوة جريئة."],"q":"الحياء","say":[],"age":""},{"cat":"مشاعر","t":"ضعف الثقة بالنفس","d":"يقول «ما أقدر» ويتجنب المحاولة.","sci":"الثقة تُبنى من تجارب النجاح الصغيرة ومن المدح المحدد للجهد، وتنهدم بالنقد المستمر والمقارنة والحماية الزائدة.","steps":["أعطه مهاماً تناسب عمره ينجح فيها.","امدح الجهد لا النتيجة فقط.","لا تُكمل عنه ما يقدر عليه.","اسمح له بالخطأ وعلّمه أن الخطأ طريق التعلم.","اكتشف موهبته ونمّها."],"q":"المؤمن القوي","say":[["أنت ما تعرف، هات أسويها","جرّب، وأنا هنا إذا احتجت"]],"age":""},{"cat":"مشاعر","t":"الحزن بعد فقد أو وفاة","d":"تأثر بوفاة قريب أو فقد صديق أو حيوان.","sci":"الأطفال يحزنون بطريقة مختلفة: قد يبدون طبيعيين ثم يحزنون فجأة، وإخفاء الحقيقة عنهم يزيد القلق.","steps":["أخبره الحقيقة بكلمات بسيطة صادقة.","اسمح له بالبكاء والسؤال.","كن قدوة: «إن العين تدمع والقلب يحزن…».","حافظ على روتينه اليومي.","علّمه الدعاء للميت.","إن استمر الحزن الشديد أشهراً فاستشر مختصاً."],"q":"الصبر","say":[],"age":""},{"cat":"مشاعر","t":"التأثر بالخلافات الزوجية أو الطلاق","d":"يبدو قلقاً أو عدوانياً أو تراجع دراسياً بعد خلاف الوالدين.","sci":"الخلاف نفسه ليس هو الأشد ضرراً، بل الصراخ أمام الطفل وجعله طرفاً أو رسولاً بين الوالدين.","steps":["لا تتشاجروا أمامه، وإن حدث فليرَ الصلح أيضاً.","لا تذمّ الطرف الآخر أمامه.","لا تجعله رسولاً ولا جاسوساً.","طمئنه أن الخلاف ليس بسببه وأن كليكما يحبه.","حافظوا على روتين ثابت.","في الطلاق: اتفقا على قواعد تربية مشتركة."],"q":"الإصلاح","say":[],"age":""},{"cat":"مشاعر","t":"الغيرة من المولود الجديد","d":"يتراجع للتصرفات الطفولية أو يؤذي المولود.","sci":"شعور طبيعي بالخوف من فقدان المكانة والحب، والتراجع المؤقت (كطلب الحفاض) شائع.","steps":["هيّئه قبل الولادة، واجعل المولود «هدية منه».","خصّص له وقتاً يومياً معك وحده.","أشركه في رعاية المولود.","لا تقل «أنت كبرت، اتركه»، بل اذكر مزايا كونه الأكبر.","اطلب من الزوار الاهتمام به أولاً."],"q":"العدل بين الأولاد","say":[],"age":""},{"cat":"مشاعر","t":"التعرّض للتنمّر","d":"يُضايَق أو يُسخر منه في المدرسة.","sci":"من علاماته: رفض الذهاب للمدرسة، والصداع المتكرر، وفقدان الأغراض، والعزلة. والتدخل المبكر مهم لأن التنمر يرتبط بالقلق والاكتئاب.","steps":["استمع له بهدوء وصدّقه.","لا تلمه، ولا تقل «اضربه».","تواصل مع المدرسة كتابياً.","درّبه على الرد الواثق والابتعاد وطلب المساعدة.","قوّ صداقاته الإيجابية ومواهبه.","راقب أي تنمر إلكتروني."],"q":"الظلم","say":[],"age":""},{"cat":"دراسة","t":"رفض المذاكرة والواجبات","d":"يماطل ويبكي عند المذاكرة.","sci":"الطفل يكره المذاكرة غالباً لأنها صارت مرتبطة بالصراخ والتوتر، أو لأن المهمة أطول من قدرة تركيزه.","steps":["وقت ومكان ثابتان للمذاكرة بلا شاشات.","قسّم الوقت: ٢٠ دقيقة ثم ٥ استراحة.","ابدأ بالأسهل ليشعر بالإنجاز.","اجلس قريباً للدعم لا للحل بدلاً عنه.","لا تصرخ؛ إن توترت فخذوا استراحة.","كافئ الإنجاز بوقت لعب."],"q":"العلم","say":[["أنت غبي ما تفهم!","هذا صعب فعلاً، تعال نجرب بطريقة ثانية"]],"age":""},{"cat":"دراسة","t":"ضعف التحصيل الدراسي","d":"درجاته منخفضة رغم المحاولة.","sci":"قد يكون السبب نقص نوم، أو ضعف بصر أو سمع، أو صعوبة تعلم محددة (كعسر القراءة)، أو مشكلة نفسية، وليس الكسل دائماً.","steps":["افحص النظر والسمع.","تأكد من نومه الكافي وإفطاره.","تواصل مع المعلم لمعرفة مواطن الضعف.","إن كانت الصعوبة في القراءة أو الكتابة أو الحساب تحديداً فاطلب تقييم «صعوبات التعلم».","قارن الطفل بنفسه لا بغيره."],"q":"العلم","say":[],"age":""},{"cat":"دراسة","t":"قلق الاختبارات","d":"يتوتر بشدة قبل الاختبار وينسى ما ذاكره.","sci":"القلق الشديد يعطّل الذاكرة العاملة، والطفل يلتقط توتر والديه حول الدرجات.","steps":["خفّف التركيز على الدرجة، وركّز على الاستعداد.","مذاكرة موزعة لا ليلة الاختبار.","نوم كافٍ ليلة الاختبار.","علّمه التنفس البطيء ودعاء: «اللهم لا سهل إلا ما جعلته سهلاً».","بعد الاختبار: لا تحقيق، بل «كيف كان شعورك؟»."],"q":"التوكل","say":[],"age":""},{"cat":"دراسة","t":"رفض الذهاب للمدرسة","d":"يبكي أو يشكو ألماً كل صباح.","sci":"غالباً خلفه سبب: تنمر، أو صعوبة دراسية، أو قلق انفصال، أو مشكلة مع معلم.","steps":["ابحث عن السبب بهدوء.","تواصل مع المدرسة.","لا تسمح بالغياب إلا لسبب صحي حقيقي.","روتين صباحي هادئ ومبكر.","استشر مختصاً إن استمر أسابيع."],"q":"العلم","say":[],"age":""},{"cat":"دراسة","t":"كثرة النسيان وضياع الأغراض","d":"ينسى واجباته وأدواته.","sci":"مهارات التنظيم (الوظائف التنفيذية) تنمو تدريجياً حتى العشرينات، وتحتاج إلى أدوات مساعدة.","steps":["قائمة مصورة على الباب لما يحتاجه كل يوم.","تجهيز الحقيبة ليلاً.","مكان ثابت لكل شيء.","أعطه المسؤولية تدريجياً ودعه يتحمل نتيجة النسيان أحياناً."],"q":"المسؤولية","say":[],"age":""},{"cat":"عبادة","t":"التكاسل عن الصلاة","d":"يؤخر الصلاة أو يتهرب منها.","sci":"العادة تُبنى بالتكرار المحبوب، والارتباط بالعقاب والصراخ يُنفّر. والقدوة أقوى مؤثر.","steps":["صلِّ أمامه وخذه للمسجد معك.","من السابعة: جدول صلاة بالنجوم ومكافأة أسبوعية.","ذكّره بلطف قبل الوقت بدقائق.","اربطها بمعناها: «نكلم الله».","من العاشرة: حزم مع حوار وبلا إهانة.","امدح المواظبة أمام الأسرة."],"q":"الصلاة","say":[["قم صلِّ يا كسلان!","الأذان أذّن، يلا نتوضأ ونصلي سوا"]],"age":""},{"cat":"عبادة","t":"الملل من حفظ القرآن","d":"يتضايق من الحفظ ويرفضه.","sci":"الحفظ يثبت بالتكرار القصير المتباعد أكثر من الجلسات الطويلة، والارتباط بالمتعة والإنجاز يحفّز.","steps":["جلسات قصيرة ١٠–١٥ دقيقة يومياً.","استمع معه لقارئ يحبه.","افهموا معاني الآيات بقصة.","لوحة إنجاز لكل سورة يتمها.","احتفل بختم كل جزء.","استعن بقسم «زاد البراعم» في التطبيق."],"q":"القرآن","say":[],"age":""},{"cat":"عبادة","t":"أسئلة الطفل الصعبة عن الله والموت","d":"يسأل: أين الله؟ ماذا بعد الموت؟","sci":"السؤال دليل تفكير صحي، والإجابة الصادقة البسيطة تبني الإيمان، والزجر يدفعه للبحث في مكان آخر.","steps":["رحّب بالسؤال: «سؤال جميل!».","أجب بالقرآن والسنة وبلغة عمره.","قل «لا أعرف، نبحث معاً» إن لم تعرف.","لا تخوّفه، بل ابدأ برحمة الله.","استعن بقسم «ما لا يسع المسلم جهله»."],"q":"الإيمان","say":[],"age":""},{"cat":"عبادة","t":"الصيام الأول للطفل","d":"يريد الصيام أو يصعب عليه.","sci":"الصيام تدريب تدريجي قبل البلوغ، وصحة الطفل أولوية.","steps":["ابدأ بصيام ساعات ثم نصف يوم.","سحور مغذٍّ وشرب ماء كافٍ.","أشغله وقت العصر بلعب هادئ كما كان الصحابة يفعلون.","احتفل بأول يوم كامل.","أفطره فوراً إن ظهر عليه تعب شديد أو كان مريضاً."],"q":"الصيام","say":[],"age":""},{"cat":"مراهقة","t":"التمرّد ورفض النصيحة","d":"يرفض التوجيه ويجادل كثيراً.","sci":"المراهق يبني هويته المستقلة، والدماغ العاطفي عنده أنشط من دماغ الضبط والتخطيط؛ فالأمر المباشر يثير المقاومة، والحوار يفتح الباب.","steps":["حوّل الأوامر إلى حوار واسأل عن رأيه.","اتفقوا على قواعد قليلة واضحة مع عواقبها.","اختر معاركك؛ تجاوز الصغائر.","استمع أكثر مما تتكلم.","وقت خاص معه: مشوار أو رياضة.","تذكّر أن الشاب الذي حاوره النبي ﷺ تغيّر بالحوار والدعاء."],"q":"الحوار","say":[["لأني قلت كذا وبس","خلّني أسمع رأيك، ثم أقول لك سبب قلقي"]],"age":"١٢+"},{"cat":"مراهقة","t":"العزلة وكثرة الجلوس في الغرفة","d":"لا يجلس مع الأسرة ويغلق بابه.","sci":"حاجة المراهق للخصوصية طبيعية، لكن العزلة التامة مع الحزن وتغيّر النوم والأكل وفقدان الاهتمام قد تكون علامة اكتئاب تحتاج مختصاً.","steps":["احترم خصوصيته مع وقت عائلي ثابت (وجبة يومية).","ادخل عالمه: اسأل عن اهتماماته.","لا تحوّل كل حديث إلى نصيحة.","انتبه لعلامات الاكتئاب واستشر مختصاً إن ظهرت."],"q":"الأسرة","say":[],"age":"١٢+"},{"cat":"مراهقة","t":"أصدقاء السوء","d":"تغيّر سلوكه بعد صحبة معينة.","sci":"تأثير الأقران في المراهقة قوي جداً، والمنع المباشر غالباً يزيد التمسك بهم.","steps":["اعرف أصدقاءه وأهلهم، وادعُهم للبيت.","لا تهاجم الصديق مباشرة؛ ناقش السلوك.","وفّر بيئات صحبة صالحة: نادٍ، حلقة، رياضة.","قوِّ علاقتك به لتكون مرجعه الأول.","«المرء على دين خليله»."],"q":"الصحبة","say":[],"age":"١٠+"},{"cat":"مراهقة","t":"التغيرات الجسدية والبلوغ","d":"ارتباك من تغيرات الجسم والأسئلة المحرجة.","sci":"إذا لم يسمع المراهق المعلومة الصحيحة من والديه بحياء وعلم، بحث عنها في مصادر خاطئة.","steps":["هيّئه قبل البلوغ بسنة أو سنتين.","الأب مع الولد والأم مع البنت.","علّمه أحكام الطهارة والغسل وعلامات البلوغ.","أجب بصدق وبقدر السؤال.","استعن بقسم «زاد الرفيق» و«زاد الرفيقة»."],"q":"البلوغ","say":[],"age":"٩–١٤"},{"cat":"مراهقة","t":"التعلق بالمشاهير والموضة","d":"يقلد مشاهير في اللبس والكلام.","sci":"المراهق يبحث عن نماذج يتماهى معها، والفراغ الحقيقي هو غياب القدوة القريبة.","steps":["قدّم له نماذج ملهمة من السيرة والصحابة ومن الناجحين المعاصرين.","ناقش القيم خلف التقليد لا الشكل فقط.","أعطه مساحة اختيار في المباح.","كن أنت قدوة يُعجب بها."],"q":"القدوة","say":[],"age":"١٢+"},{"cat":"مراهقة","t":"المشاعر العاطفية والإعجاب","d":"تعلق عاطفي بالجنس الآخر أو محادثات خفية.","sci":"المشاعر في المراهقة طبيعية بسبب التغيرات الهرمونية، والمهم توجيهها لا إنكارها، والقرب من الوالدين يحمي.","steps":["لا تصدم ولا تفضح؛ حاور بهدوء.","اعترف بالمشاعر ووجّه السلوك.","بيّن الحكم الشرعي برفق وأسبابه.","اشغله بأهداف ونشاطات.","راقب الأجهزة باتفاق واضح.","للشباب: «يا معشر الشباب…»."],"q":"العفة","say":[],"age":"١٢+"},{"cat":"أمان","t":"إدمان الشاشات والألعاب الإلكترونية","d":"غضب شديد عند سحب الجهاز وانشغال دائم به.","sci":"الألعاب والمقاطع القصيرة مصممة لإفراز «الدوبامين» بشكل متكرر، فيصعب التوقف. وكثرتها ترتبط بقلة النوم وضعف الانتباه.","steps":["لا شاشات قبل سنتين، وساعة على الأكثر حتى الخامسة.","لا أجهزة في غرف النوم ليلاً.","تنبيه قبل انتهاء الوقت بـ١٠ دقائق.","وفّر بدائل: لعب، ورياضة، وقراءة، وزيارات.","اتفقوا جميعاً على قواعد واضحة، وكونوا قدوة."],"q":"اللهو","say":[],"age":""},{"cat":"أمان","t":"المحتوى غير المناسب على الإنترنت","d":"شاهد محتوى عنيفاً أو إباحياً.","sci":"التعرّض المبكر للمحتوى الإباحي يؤثر في نظرة الطفل للجسد والعلاقات، والإنكار الغاضب يجعله يخفي ما يحدث.","steps":["ابقَ هادئاً واشكره إن أخبرك.","بيّن بلطف أن هذا ضار وحرام ولماذا.","فعّل الرقابة الأبوية وفلترة المحتوى.","الأجهزة في الأماكن المشتركة.","حوار دوري مفتوح: «أخبرني إن رأيت شيئاً أزعجك»."],"q":"غض البصر","say":[],"age":""},{"cat":"أمان","t":"الحماية من التحرش","d":"كيف أحمي طفلي من التحرش؟","sci":"معظم حالات التحرش تحدث من أشخاص يعرفهم الطفل، والطفل الذي يعرف قواعد جسده ويثق بوالديه يكون أكثر أماناً.","steps":["علّمه أسماء أعضاء جسده الصحيحة وأن العورة لا يلمسها أحد.","قاعدة: لا أسرار عن الوالدين، والسر المحرج يُقال لأمي وأبي.","لا تجبره على تقبيل أو حضن أحد.","اعرف من يخلو به: سائق، عامل، قريب.","صدّقه دائماً إن أخبرك، وتواصل مع الجهات المختصة."],"q":"العورة","say":[],"age":""},{"cat":"أمان","t":"التواصل مع الغرباء في الألعاب","d":"يتحدث مع أشخاص مجهولين عبر الألعاب.","sci":"كثير من المتحرشين والمحتالين يستخدمون الألعاب الجماعية والمحادثات للوصول إلى الأطفال.","steps":["أغلق المحادثة مع الغرباء في إعدادات اللعبة.","علّمه: لا معلومات ولا صور ولا لقاءات.","أي طلب سرّي أو صورة: يخبرك فوراً.","العب معه أحياناً لتعرف عالمه."],"q":"الأمانة","say":[],"age":""},{"cat":"إخوة","t":"الغيرة بين الإخوة","d":"تنافس وغيرة مستمرة.","sci":"شعور طبيعي يزيد مع قدوم مولود جديد أو التفضيل.","steps":["اعدل في العطاء والمدح والوقت.","خصّص لكل طفل وقتاً منفرداً معك.","لا تقارن بين الأولاد أبداً.","أشرك الكبير في رعاية المولود ليشعر بالمكانة."],"q":"العدل بين الأولاد","say":[],"age":""},{"cat":"إخوة","t":"الشجار الدائم بين الإخوة","d":"خلافات وصراخ وضرب متكرر.","sci":"تدخّل الوالدين الدائم كقاضٍ يزيد الشجار أحياناً؛ لأن الأطفال يتنافسون على انتباههم.","steps":["في الخلاف البسيط: اتركهم يحلونه وراقب من بعيد.","في الضرب: افصل فوراً بلا محاكمة طويلة.","علّمهم مهارة الحل: كل واحد يقول ما يريد، ثم يقترحون حلاً.","قواعد بيت واضحة للجميع.","امدحهم حين يلعبون بسلام."],"q":"الإصلاح","say":[],"age":""},{"cat":"إخوة","t":"تحميل الابن الأكبر مسؤوليات فوق طاقته","d":"الكبير يربي إخوته ويتحمل أخطاءهم.","sci":"إعطاء الكبير دور الوالد يحرمه من طفولته ويولّد ضغطاً واستياءً من إخوته.","steps":["مسؤوليات تناسب عمره فقط.","لا تحاسبه على أخطاء إخوته.","امنحه امتيازات تناسب مسؤولياته.","اشكره على مساعدته ولا تعتبرها واجباً دائماً."],"q":"العدل","say":[],"age":""},{"cat":"عادات","t":"مصّ الإصبع وقضم الأظافر","d":"عادة متكررة خاصة عند التوتر.","sci":"وسيلة تهدئة ذاتية، وتختفي غالباً مع العمر، والتركيز عليها والانتقاد يزيدها.","steps":["تجاهلها عند الصغير، وانتبه لأسباب التوتر.","أشغل يديه بنشاط.","تذكير خفي متفق عليه بدل التوبيخ.","مكافأة على الأيام الخالية.","استشر طبيب الأسنان إن استمرت بعد ظهور الأسنان الدائمة."],"q":"الرفق","say":[],"age":""},{"cat":"عادات","t":"السمنة وقلة الحركة","d":"زيادة الوزن وقلة النشاط.","sci":"نمط حياة الأسرة يحدد عادات الطفل؛ والتركيز على الصحة والحركة أنفع من الحمية والحديث عن الوزن.","steps":["غيّروا عادات الأسرة كلها لا الطفل وحده.","ساعة حركة يومياً على الأقل.","ماء بدل العصائر والمشروبات الغازية.","لا تجعل الطعام مكافأة أو عقاباً.","لا تعلّق على شكله؛ تكلم عن الصحة.","راجع طبيب الأطفال لمتابعة النمو."],"q":"الطعام","say":[],"age":""},{"cat":"عادات","t":"إهمال النظافة الشخصية","d":"يرفض الاستحمام وتنظيف الأسنان.","sci":"العادات اليومية تحتاج روتيناً ثابتاً وتذكيراً، والمراهق يحتاج معلومة عن تغيّرات جسمه.","steps":["روتين ثابت مرتبط بأوقات معينة.","اجعلها ممتعة للصغار: أغنية أو مؤقت.","اربطها بالسنة: «الطهور شطر الإيمان»، والسواك.","للمراهق: حوار عن تغيرات البلوغ ومزيل العرق."],"q":"النظافة","say":[],"age":""},{"cat":"عادات","t":"تحمّل المسؤولية والاعتماد على النفس","d":"يعتمد على والديه في كل شيء.","sci":"الحماية الزائدة والقيام بكل شيء عن الطفل تُضعف مهاراته وثقته، والمسؤولية تُبنى بالمهام الصغيرة المتدرجة.","steps":["مهام منزلية حسب العمر: ٣ سنوات يرتب ألعابه، ٦ يجهز حقيبته، ١٠ يساعد في الطبخ.","دعه يحاول ولو أخطأ.","لا تُعِد ما فعله إن لم يكن متقناً تماماً.","اشكره على مساهمته.","«كلكم راعٍ»."],"q":"المسؤولية","say":[],"age":""},{"cat":"عادات","t":"تبذير المال وعدم تقدير قيمته","d":"يطلب كثيراً ولا يقدّر ما عنده.","sci":"الطفل يتعلم قيمة المال حين يديره بنفسه ويرى أثر قراراته.","steps":["مصروف ثابت مناسب للعمر.","ثلاث حصالات: للإنفاق، والادخار، والصدقة.","دعه يدّخر لشيء يريده.","أشركه في ميزانية بسيطة للبيت.","«ولا تبذر تبذيراً»."],"q":"الإسراف","say":[],"age":""},{"cat":"عادات","t":"قلة النوم عند المراهق","d":"يسهر حتى الفجر وينام في النهار.","sci":"ساعة المراهق البيولوجية تتأخر طبيعياً، لكن الشاشات ليلاً تزيد التأخير، وقلة النوم تؤثر في المزاج والتحصيل.","steps":["اتفاق على وقت تُغلق فيه الأجهزة.","الأجهزة تُشحن خارج غرفة النوم.","صلاة الفجر مع الأسرة تثبّت الإيقاع.","تجنب المنبهات (القهوة ومشروبات الطاقة) مساءً.","المراهق يحتاج ٨–١٠ ساعات نوم."],"q":"النوم","say":[],"age":"١٢+"},{"cat":"صغار","t":"كثرة البكاء والأنين","d":"يطلب كل شيء بالبكاء والأنين.","sci":"الأنين يستمر إذا كان هو الطريق الوحيد الذي يُلبّى به الطلب.","steps":["قل بهدوء: «أسمعك أكثر بصوتك العادي».","لبِّ الطلب المعقول فور طلبه بصوت هادئ.","تجاهل الأنين نفسه دون تجاهل الطفل.","تحقق من الجوع والنعاس والتعب."],"q":"الرفق","say":[["بطّل نِق!","قلها بصوتك الطبيعي وأنا أسمعك"]],"age":"٢–٦"},{"cat":"صغار","t":"الخوف من الطبيب والإبر","d":"يصرخ ويرفض الكشف.","sci":"الخوف من الألم والمجهول طبيعي، والكذب عليه يجعل الزيارة التالية أصعب.","steps":["أخبره بالحقيقة ببساطة قبلها بقليل.","العب معه لعبة «الطبيب» في البيت.","احمله وضمّه وقت الإبرة.","امدح شجاعته بعدها وأعطه شيئاً يحبه."],"q":"الصبر","say":[],"age":"١–٧"},{"cat":"صغار","t":"رفض مشاركة السرير أو النوم في غرفته","d":"يرفض النوم وحده.","sci":"الانتقال للنوم المستقل يحتاج تدرجاً، والتفريق في المضاجع من العاشرة سنة نبوية.","steps":["اجعل غرفته جذابة ومريحة.","اجلس بجانبه أولاً، ثم ابتعد تدريجياً كل ليلة.","روتين نوم ثابت مع الأذكار.","امدحه صباحاً على نومه وحده."],"q":"النوم","say":[],"age":"٣–١٠"},{"cat":"صغار","t":"الطفل الذي يقاطع الكلام دائماً","d":"يقاطع والديه في الحديث والهاتف.","sci":"الصغير لا يقدّر الوقت بعد، ويحتاج إشارة واضحة أنه سيُسمع.","steps":["علّمه إشارة: يضع يده على يدك وتضغط عليها أنت: «رأيتك».","التفت إليه بعد لحظات فعلاً.","امدحه حين ينتظر.","جهّز له نشاطاً قبل مكالمة طويلة."],"q":"الأدب","say":[],"age":"٣–٧"},{"cat":"سلوك","t":"الطفل الذي يتهم الآخرين دائماً","d":"يقول دائماً: «هو اللي بدأ».","sci":"إلقاء اللوم يحمي الطفل من العقاب ومن الشعور بالذنب، ويقل إذا شعر أن الخطأ فرصة للإصلاح لا للفضيحة.","steps":["ركّز على الإصلاح لا على من بدأ.","اسأل: «ما الذي تقدر أنت تفعله الآن؟».","كن قدوة في الاعتراف بخطئك.","امدح الاعتراف."],"q":"الاعتراف","say":[],"age":""},{"cat":"سلوك","t":"التمارض والتحجج للتهرب","d":"يشتكي من ألم كلما طُلب منه شيء.","sci":"قد يكون ألماً حقيقياً من القلق (فالقلق يسبب مغصاً وصداعاً فعلاً)، أو وسيلة للهروب من مهمة صعبة.","steps":["خذ الشكوى بجدية وافحصه، وراجع الطبيب إن تكررت.","ابحث عما يتهرب منه.","لا تجعل المرض مكافأة (شاشات طوال اليوم).","ساعده في مواجهة المهمة الصعبة بخطوات صغيرة."],"q":"الصدق","say":[],"age":""},{"cat":"سلوك","t":"الطفل المدلّل الذي لا يقبل «لا»","d":"يغضب بشدة عند الرفض.","sci":"إذا اعتاد الطفل أن «لا» تتحول إلى «نعم» مع الإلحاح، صارت كل «لا» بداية معركة.","steps":["قل «لا» قليلاً، لكن إذا قلتها فالتزم بها.","اشرح السبب مرة واحدة باختصار.","اتفق مع الزوج والأجداد على موقف واحد.","تقبّل غضبه دون أن تتراجع.","علّمه الصبر والقناعة بالقصص والقدوة."],"q":"القناعة","say":[["طيب طيب خذه بس اسكت","فاهم إنك زعلان، والجواب لا يزال لا"]],"age":""},{"cat":"سلوك","t":"التخريب وتكسير الأغراض","d":"يكسر الألعاب والأثاث.","sci":"عند الصغار غالباً فضول واستكشاف، وعند الأكبر قد يكون تعبيراً عن غضب أو طلباً للاهتمام.","steps":["فرّق بين الاستكشاف والتخريب المقصود.","وفّر ألعاب فك وتركيب.","عاقبة منطقية: يصلح أو يساهم من مصروفه.","علّمه طرقاً آمنة لتفريغ الغضب: رياضة، رسم."],"q":"الإصلاح","say":[],"age":""},{"cat":"سلوك","t":"الطفل الكثير الأسئلة","d":"يسأل «لماذا؟» بلا توقف.","sci":"الأسئلة علامة ذكاء ونمو، ويتراجع الفضول إذا قوبل بالزجر.","steps":["أجب بإيجاز، واسأله: «وأنت ما رأيك؟».","إن كنت مشغولاً: «سؤال رائع، نبحث عنه بعد العشاء».","ابحثوا معاً في كتاب أو التطبيق.","لا تسخر من أي سؤال."],"q":"العلم","say":[],"age":""},{"cat":"سلوك","t":"السلوك السيئ أمام الضيوف أو في الأماكن العامة","d":"يفتعل المشاكل أمام الناس.","sci":"الطفل يلاحظ أن والديه يتراخيان أمام الناس، أو يشعر بالملل والإهمال وقت الزيارة.","steps":["اتفق معه قبل الخروج على القواعد والمكافأة.","جهّز نشاطاً يشغله.","خذه جانباً بهدوء عند الخطأ ولا توبّخه أمام الناس.","نفّذ العاقبة المتفق عليها في البيت."],"q":"الأدب","say":[],"age":""},{"cat":"مشاعر","t":"الحساسية الزائدة وسرعة البكاء","d":"يبكي من أبسط تعليق.","sci":"بعض الأطفال مزاجهم حساس بطبيعتهم، وهذه ليست ضعفاً، ويحتاجون إلى مساعدة في تسمية مشاعرهم وتنظيمها.","steps":["لا تقل «أنت حساس زيادة».","سمِّ الشعور واعترف به.","علّمه التنفس العميق وطرق التهدئة.","قلّل النقد العلني.","نمِّ نقاط قوته؛ فالحساس غالباً رحيم ومبدع."],"q":"الرحمة","say":[],"age":""},{"cat":"مشاعر","t":"كثرة الشكوى والتذمّر","d":"يتذمّر من كل شيء.","sci":"التذمّر عادة تُكتسب من البيئة، والتدرب على الامتنان يغيّر طريقة التفكير مع الوقت.","steps":["كن قدوة: قلّل التذمّر أمامه.","لعبة يومية على العشاء: «ثلاث نِعَم اليوم».","إذا اشتكى قل: «ما الحل الذي تقترحه؟».","علّمه «الحمد لله على كل حال»."],"q":"الشكر","say":[],"age":""},{"cat":"مشاعر","t":"الطفل الذي يخاف الفشل ويرفض المنافسة","d":"ينسحب من المسابقات خوفاً من الخسارة.","sci":"التركيز الزائد على النتائج والمدح بـ«أنت ذكي» يجعل الطفل يخاف أن يفقد هذا الوصف، فيتجنب التحدي.","steps":["امدح الجهد والمحاولة.","احكِ له عن أخطائك وكيف تعلمت منها.","العبوا ألعاباً فيها ربح وخسارة.","اجعل الخسارة فرصة: «ماذا تعلمنا؟»."],"q":"الصبر","say":[],"age":""},{"cat":"مشاعر","t":"الكوابيس والأحلام المزعجة","d":"يستيقظ خائفاً من حلم.","sci":"الكوابيس شائعة بين ٣ و٦ سنوات، وتزيد مع المشاهد المخيفة والتوتر.","steps":["اهدأ واحضنه وطمئنه.","علّمه السنة: يتفل عن يساره ثلاثاً، ويستعيذ بالله، ويتحول لجنبه الآخر، ولا يحدّث بها.","تجنب المشاهد المخيفة مساءً.","إن تكررت كثيراً مع ضيق نهاري فاستشر مختصاً."],"q":"الرؤيا","say":[],"age":""},{"cat":"مشاعر","t":"الطفل بعد الانتقال لبيت أو مدرسة جديدة","d":"حزين أو متوتر بعد التغيير.","sci":"التغيير يفقد الطفل إحساسه بالأمان المألوف، ويحتاج وقتاً من أسابيع لأشهر للتأقلم.","steps":["هيّئه قبل الانتقال وزوروا المكان.","حافظ على روتين البيت كما هو.","ساعده على التواصل مع أصدقائه القدامى.","شجّعه على صداقة جديدة واحدة أولاً."],"q":"الصبر","say":[],"age":""},{"cat":"دراسة","t":"ضعف القراءة والكتابة","d":"يقرأ ببطء ويخطئ كثيراً.","sci":"القراءة مهارة تتطلب تدريباً يومياً، وقد تكون هناك صعوبة تعلّم محددة (عسر القراءة) تحتاج تقييماً.","steps":["القراءة المشتركة ١٥ دقيقة يومياً.","كتب يحبها ولو قصص مصورة.","اقرأ أمامه؛ القدوة تصنع القارئ.","استعن بقسم «زاد الكبار والأميين» وتمارين الحروف.","إن استمرت الصعوبة رغم التدريب فاطلب تقييماً متخصصاً."],"q":"القراءة","say":[],"age":""},{"cat":"دراسة","t":"الغش في الاختبارات","d":"ضُبط وهو يغش.","sci":"الغش يزيد مع الضغط الشديد على الدرجات والخوف من العقاب.","steps":["تحدّث عن الأمانة: «من غشنا فليس منا».","خفّف الضغط على الدرجة وركز على التعلّم.","ساعده على الاستعداد الجيد.","دعه يتحمل العاقبة المدرسية، وكن داعماً لا فاضحاً."],"q":"الغش","say":[],"age":""},{"cat":"دراسة","t":"الاعتماد الكامل على الوالدين في الواجبات","d":"لا يحل واجبه إلا وأحد والديه معه.","sci":"الحل بدلاً عنه يعطيه رسالة أنه غير قادر، ويحرمه من مهارة التعلم الذاتي.","steps":["قل: «ابدأ وحدك، وأنا أراجع معك بعد ٢٠ دقيقة».","ساعده بالسؤال لا بالإجابة.","زد استقلاليته تدريجياً.","امدح ما حلّه وحده."],"q":"المسؤولية","say":[],"age":""},{"cat":"عبادة","t":"الطفل الذي يستعجل في الصلاة وينقرها","d":"يصلي بسرعة دون خشوع.","sci":"الخشوع يُتعلم بالفهم والقدوة، وليس بالانتقاد المتكرر.","steps":["علّمه معنى ما يقول في الصلاة.","صلِّ معه جماعة وأطِل قليلاً.","حديث المسيء صلاته: علّمه الطمأنينة بلطف.","امدح الصلاة الهادئة."],"q":"الخشوع","say":[],"age":""},{"cat":"عبادة","t":"الملل من الذهاب للمسجد","d":"يرفض الذهاب للمسجد أو يلعب فيه.","sci":"المسجد يصبح محبوباً إذا ارتبط بتجربة جميلة وبالترحيب لا بالزجر.","steps":["خذه في الأوقات القصيرة (المغرب).","علّمه آداب المسجد قبل الذهاب.","كافئه بعدها: مشوار أو حلوى.","عرّفه على أطفال المسجد والإمام."],"q":"المسجد","say":[],"age":""},{"cat":"عبادة","t":"التشكيك والأسئلة الإلحادية عند المراهق","d":"يطرح شبهات عن وجود الله أو الدين.","sci":"المراهق يتعرض لشبهات كثيرة عبر الإنترنت، والانفعال أو التخويف يغلق باب الحوار.","steps":["اشكره أنه سألك أنت.","لا تنفعل ولا تتهمه.","ابحثوا معاً في الأدلة: قسم «الدعوة إلى الله» في التطبيق فيه ردود على اللادينيين بالحجة.","اربطه بطالب علم ثقة.","اهتم بالجانب العاطفي: هل وراء السؤال ضيق أو أزمة؟"],"q":"الإيمان","say":[],"age":"١٣+"},{"cat":"مراهقة","t":"المراهق الكثير الغضب","d":"ينفجر غاضباً لأسباب بسيطة.","sci":"التغيرات الهرمونية ونشاط مراكز الانفعال تجعل المراهق أسرع انفعالاً، لكنه يتعلم الضبط بالتدريب والقدوة.","steps":["لا تنفعل معه؛ أجّل الحديث حتى يهدأ.","علّمه الهدي النبوي في الغضب.","الرياضة تفرغ التوتر.","ابحث عن أسباب: ضغط دراسي، أصدقاء، قلة نوم.","إن صاحبه إيذاء للنفس أو للآخرين فاستشر مختصاً فوراً."],"q":"الغضب","say":[],"age":"١٢+"},{"cat":"مراهقة","t":"التدخين أو التجربة الخطرة","d":"اكتشفت أنه يدخن أو يجرب شيئاً خطراً.","sci":"المراهق يجرب بدافع الفضول وضغط الأقران وإثبات الذات، والتعامل الهادئ يفتح الحوار والتعامل العنيف يدفعه للإخفاء.","steps":["اهدأ واجمع المعلومات أولاً.","تحاور عن الأضرار الصحية والحكم الشرعي.","ضع حدوداً واضحة وعواقب.","اعرف أصدقاءه ومصادر الحصول عليه.","في المخدرات: اطلب مساعدة مختصة فوراً."],"q":"الخمر","say":[],"age":"١٢+"},{"cat":"مراهقة","t":"المراهق الذي لا يتحدث مع والديه","d":"إجاباته «عادي، ماشي، ولا شي».","sci":"المراهق يتحدث أكثر في المواقف الجانبية (في السيارة، أثناء نشاط) لا في جلسات التحقيق المباشر.","steps":["استغل أوقات السيارة والمشي.","اسأل أسئلة مفتوحة محددة.","استمع بلا مقاطعة ولا وعظ فوري.","شاركه أنت قصصك وأخطاءك."],"q":"الحوار","say":[],"age":"١٢+"},{"cat":"مراهقة","t":"هوس المظهر والوزن عند المراهقين","d":"قلق شديد من شكله ووزنه.","sci":"المقارنة بصور المؤثرين المعدّلة ترتبط بعدم الرضا عن الجسم، وقد تتطور لاضطرابات أكل.","steps":["لا تعلّق على وزنه أو شكله ولا وزن غيره.","ركّز على الصحة والقوة لا الشكل.","ناقش حقيقة الصور المعدّلة.","إن لاحظت تقييداً شديداً للأكل أو تقيؤاً فاستشر طبيباً فوراً."],"q":"الشكر","say":[],"age":"١٢+"},{"cat":"أمان","t":"الطفل الذي يُترك مع الخادمة طويلاً","d":"يقضي معظم وقته مع العاملة المنزلية.","sci":"الطفل يتعلق بمن يقضي معه الوقت ويكتسب لغته وقيمه، والتربية لا تُفوّض كاملة.","steps":["حدّد دور العاملة بالخدمة لا بالتربية.","وقت يومي ثابت للأم والأب مع الطفل.","لا تتركه يخلو معها أو مع السائق لفترات طويلة.","راقب ما يشاهده ويسمعه."],"q":"الرعاية","say":[],"age":""},{"cat":"أمان","t":"تصوير الأطفال ونشر صورهم","d":"نشر صور الأطفال في وسائل التواصل.","sci":"صور الأطفال المنشورة قد تُسرق أو تُستغل، وتبقى رقمياً مدى الحياة دون إذنهم.","steps":["لا تنشر صوراً تكشف المدرسة أو المكان أو العورة.","اجعل حساباتك خاصة.","اسأل الطفل الأكبر قبل النشر.","علّم أولادك ألا ينشروا صورهم وصور غيرهم."],"q":"الستر","say":[],"age":""},{"cat":"إخوة","t":"التفضيل غير المقصود لأحد الأبناء","d":"يشعر أحدهم أن أخاه المفضّل.","sci":"حتى لو لم تقصد، فإن الطفل يلتقط فروق النبرة والوقت والمدح.","steps":["اسأل كل ابن: «هل تشعر أني أفضّل أحداً؟».","وقت خاص لكل واحد.","لا تقارن.","العدل في الهدايا واجب: «اعدلوا بين أولادكم»."],"q":"العدل بين الأولاد","say":[],"age":""},{"cat":"إخوة","t":"الأخ الذي يتسلّط على أخواته","d":"يتحكم بأخواته ويقسو عليهن باسم الرجولة.","sci":"القوامة والرجولة الحقيقية حماية ورحمة لا تسلّط، والطفل يتعلم ذلك من معاملة الأب للأم.","steps":["علّمه أن الرجولة رحمة وحماية.","لا تمنحه سلطة على أخواته.","الأب قدوة في احترام الأم والبنات.","«خيركم خيركم لأهله»."],"q":"الرحمة","say":[],"age":""},{"cat":"عادات","t":"الإدمان على السكريات والوجبات السريعة","d":"يرفض الطعام الصحي.","sci":"الأطعمة المصنّعة مصممة لتكون مرغوبة جداً، والذوق يتعود تدريجياً على الطعام الصحي.","steps":["لا تشترِها للبيت أصلاً.","خيارات صحية متاحة دائماً (فواكه، مكسرات للأكبر).","الحلوى في أوقات محددة لا مكافأة.","اطبخوا معاً وجبات صحية لذيذة."],"q":"الطعام","say":[],"age":""},{"cat":"عادات","t":"كثرة المزاح الجارح والسخرية","d":"يسخر من الآخرين ويجرحهم بالمزاح.","sci":"يتعلم الطفل السخرية من البيت والمقاطع الكوميدية، ولا يدرك أثرها دون توجيه.","steps":["بيّن الفرق بين المزاح والسخرية.","﴿لا يسخر قوم من قوم﴾.","اطلب منه الاعتذار.","كن قدوة: لا سخرية في البيت."],"q":"السخرية","say":[],"age":""},{"cat":"عادات","t":"عدم الوفاء بالوعود والمواعيد","d":"لا يلتزم بما يتفق عليه.","sci":"الالتزام يتعلمه الطفل من وفاء والديه بوعودهم له أولاً.","steps":["أوفِ أنت بوعودك له.","اكتبوا الاتفاقات.","عواقب واضحة عند عدم الالتزام.","امدح الوفاء.","«آية المنافق ثلاث…»."],"q":"الوعد","say":[],"age":""},{"cat":"عادات","t":"اللغة: ضعف العربية وكثرة الكلام بالإنجليزية","d":"لا يتقن العربية ويتكلم الإنجليزية غالباً.","sci":"اللغة الأم تُحفظ بالاستعمال اليومي، والأطفال قادرون على إتقان أكثر من لغة إذا كان لكل لغة مساحتها.","steps":["العربية لغة البيت.","قصص عربية يومياً ورسوم كرتونية بالفصحى.","حفظ القرآن والأناشيد.","استعن بقسم «علوم العربية» للكبار."],"q":"العربية","say":[],"age":""}],"sources":[{"cat":"كتب في المكتبة يرجع إليها هذا القسم","items":[{"t":"القرآن الكريم وتفاسيره: ابن كثير، والطبري، والقرطبي، والسعدي","href":"#/library"},{"t":"صحيح البخاري، وصحيح مسلم، والسنن، ومسند أحمد","href":"#/library"},{"t":"رياض الصالحين للنووي: كتاب الأدب، وباب حق الأولاد","href":"#/book/riyad"},{"t":"الأدب المفرد للبخاري: أبواب الوالدين والولد","href":"#/book/adab"},{"t":"زاد المعاد لابن القيم: هديه ﷺ في العقيقة والتسمية والختان","href":"#/item/zad:246"},{"t":"فتح الباري، والمنهاج شرح مسلم: شروح الأحاديث","href":"#/library"}]},{"cat":"كتب مشهورة في التربية للاستزادة (ليست داخل التطبيق)","items":[{"t":"تحفة المودود بأحكام المولود — ابن قيم الجوزية","href":""},{"t":"تربية الأولاد في الإسلام — عبد الله ناصح علوان","href":""},{"t":"منهج التربية النبوية للطفل — محمد نور سويد","href":""}]}],"intro":{"ayah":"﴿يا أيها الذين آمنوا قوا أنفسكم وأهليكم نارًا﴾ (التحريم: 6)","hadith":"قال النبي ﷺ: «كلكم راعٍ وكلكم مسؤول عن رعيته... والمرأة راعية في بيت زوجها ومسؤولة عن رعيتها» (متفق عليه).","note":"التربية مسؤولية الأب والأم معاً، والأم هي المدرسة الأولى، ويتغيّر دور الوالدين مع كل مرحلة: من الرعاية الكاملة، إلى التوجيه، إلى الصحبة، إلى المشورة، وأخيراً الدعاء."},"stages":[{"id":"infant","name":"الرضيع","age":"من الولادة إلى سنتين","role":"دورك: الأمان والحب والرعاية الكاملة","common":["التحنيك والعقيقة سنة، قال ﷺ: «كل غلام رهينة بعقيقته، تُذبح عنه يوم سابعه، ويُحلق، ويُسمّى» (رواه أبو داود والترمذي وصححه).","اختاروا له اسماً حسناً، فالاسم أول هدية للمولود.","الرضاعة الطبيعية حولان لمن أراد الإتمام: ﴿والوالدات يرضعن أولادهن حولين كاملين﴾ (البقرة: 233)، وتوصي منظمة الصحة العالمية بالرضاعة الطبيعية وحدها في الأشهر الستة الأولى.","التطعيمات في مواعيدها بحسب جدول وزارة الصحة، واحفظوا بطاقة التطعيم دائماً.","يتعلّم الطفل الأمان من حضن والديه وأصواتهم؛ فاحملوه وكلّموه وابتسموا له، وليس هذا تدليلاً.","نوّموه على ظهره في سرير مستقل، بلا وسائد ولا ألعاب حوله، تقليلاً لخطر الموت المفاجئ للرضّع.","أسمعوه القرآن والأذكار بأصواتكم، فهو يحفظ نغمة الصوت قبل الكلام."],"boys":["الختان من سنن الفطرة: «الفطرة خمس: الختان، والاستحداد...» (متفق عليه)، ويُجرى عند طبيب في الأشهر الأولى غالباً.","العقيقة عن الغلام شاتان (رواه الترمذي وصححه)."],"girls":["العقيقة عن الجارية شاة (رواه الترمذي وصححه).","استقبلوها بالفرح، فكراهية البنات من أخلاق الجاهلية: ﴿وإذا بُشّر أحدهم بالأنثى ظل وجهه مسودًا وهو كظيم﴾ (النحل: 58).","ختان الإناث الضارّ ممنوع قانوناً في مصر، وأفتت دار الإفتاء المصرية بتحريمه لما فيه من ضرر ثابت طبياً."]},{"id":"early","name":"الطفولة المبكرة","age":"من سنتين إلى ست سنوات","role":"دورك: القدوة واللعب وغرس محبة الله","common":["علّموه أن الله يحبه ويرزقه ويراه، وابدؤوا بالحب قبل الخوف.","حفّظوه الفاتحة والمعوذتين وأذكاراً يسيرة: «بسم الله» قبل الطعام، و«الحمد لله» بعده.","اللعب حق الطفل؛ كان النبي ﷺ يداعب الصغار، وقال لصبي مات عصفوره: «يا أبا عمير، ما فعل النُّغير؟» (متفق عليه).","الشاشات: ينصح الأطباء ألا تزيد على ساعة يومياً من سنتين إلى خمس، وبمحتوى مناسب.","الطفل يقلّد أكثر مما يسمع؛ فصلّوا أمامه، واقرؤوا القرآن أمامه، ودعوه يراكم تعتذرون إذا أخطأتم.","علّموه خصوصية جسده: لا يلمس أحدٌ عورته، وأن يخبر والديه بأي سرّ يُطلب منه كتمانه.","العدل بين الإخوة في المحبة والهدايا: «اتقوا الله واعدلوا بين أولادكم» (متفق عليه)."],"boys":["الولد يحتاج إلى الحضن والكلمة الطيبة كالبنت تماماً، وعبارة «لا تبكِ، أنت رجل» ليست تربية صحيحة.","أشركوه في أعمال البيت؛ فقد كان النبي ﷺ في مهنة أهله (رواه البخاري)."],"girls":["امدحوا أخلاقها وذكاءها، لا شكلها وحده.","علّموها الحياء بالتدريج وبالقدوة، دون تخويف ولا تعييب مبالغ فيه."]},{"id":"school","name":"سن التمييز والمدرسة","age":"من سبع إلى عشر سنوات","role":"دورك: التعليم والتدريب على العبادة","common":["الصلاة: «مُروا أولادكم بالصلاة وهم أبناء سبع سنين، واضربوهم عليها وهم أبناء عشر، وفرّقوا بينهم في المضاجع» (رواه أبو داود، وحسّنه الألباني). وقرر العلماء أن الضرب هنا تأديب غير مؤذٍ ولا في الوجه، وأن ثلاث سنوات من التدريب بالتحفيز تكفي غالباً دون الحاجة إليه.","فرّقوا بين الأولاد في المضاجع من سن العاشرة.","شجّعوه على حفظ القرآن بالتدريج، مع المكافأة.","تابعوا دراسته دون أن تذاكروا عنه، وعلّموه الاعتماد على نفسه.","اعرفوا أصحابه وأهلهم.","أنصتوا إليه حين يحكي عن يومه ولا تقاطعوه، فهذا يبني ثقة تحتاجونها في المراهقة.","علّموه أدب الاستئذان قبل دخول غرفتكم: ﴿ليستأذنكم الذين ملكت أيمانكم والذين لم يبلغوا الحلم منكم ثلاث مرات﴾ (النور: 58)."],"boys":["ليذهب إلى المسجد مع أبيه، ويحضر صلاة الجمعة.","وجّهوا طاقته الكبيرة إلى رياضة كالسباحة أو الكرة أو الدفاع عن النفس.","علّموه احترام البنات وأخواته، وأن يحميهن دون تسلّط."],"girls":["حبّبوها في الحجاب بالقدوة والهدية، لا بالإجبار.","قد تأتي الدورة من سن التاسعة، فمهّدي لها بهدوء.","شجّعوها على الرياضة والهوايات والتفوق."]},{"id":"puberty","name":"البلوغ","age":"من عشر إلى أربع عشرة سنة تقريباً","role":"دورك: التمهيد والمصارحة والطمأنة","common":["بالبلوغ يبدأ التكليف: الصلاة والصيام فرض، وتُكتب الحسنات والسيئات.","حدّثوه عن التغيّرات قبل وقوعها، حتى لا يتلقى معلومات خاطئة من أصحابه أو من الإنترنت.","علّموه الغسل وأحكام الطهارة خطوة خطوة.","احترموا خصوصيته، واطرقوا الباب قبل الدخول.","تقلّب المزاج طبيعي بسبب الهرمونات، فلا تحملوه على قلة الأدب."],"boys":["علامات البلوغ: الاحتلام، ونبات شعر العانة، وخشونة الصوت، أو إتمام خمس عشرة سنة هجرية إن لم تظهر علامة.","بيّنوا له أن الاحتلام طبيعي وليس ذنباً، وأن بعده الغسل، والأفضل أن يتولى الأب البيان.","للأب هنا دور أكبر: صحبة الولد ومصارحته.","غضّ البصر والعفّة: ﴿قل للمؤمنين يغضوا من أبصارهم﴾ (النور: 30)، وحدّثوه عن خطر المواد الإباحية بهدوء."],"girls":["علامات البلوغ: الحيض، أو الاحتلام، أو نبات شعر العانة، أو إتمام خمس عشرة سنة هجرية.","جهّزي لها حقيبة صغيرة فيها فُوَط في حقيبة المدرسة قبل أول دورة.","علّميها متى تبدأ الدورة، وعلامات الطهر، والغسل، وما يحرم في الحيض، ويساعدها قسم «رفيقة».","الحجاب فرض بعد البلوغ: ﴿وليضربن بخمرهن على جيوبهن﴾ (النور: 31)، فبيّني لها الحكمة وكوني قدوتها.","اجعليها تشعر أن أول دورة مناسبة سعيدة، وأنها كبرت."]},{"id":"teen","name":"المراهقة","age":"من أربع عشرة إلى ثماني عشرة سنة","role":"دورك: الصحبة والحوار والثقة","common":["تحوّلوا من الآمر إلى الصاحب، وقد اشتهر في الأثر: «لاعبه سبعًا، وأدّبه سبعًا، وصاحبه سبعًا».","الحوار قبل المنع: جاء شاب إلى النبي ﷺ يستأذنه في الزنا، فلم يزجره، بل حاوره: «أتحبه لأمك؟... لأختك؟...»، ثم دعا له (رواه أحمد، وصححه الألباني).","الجوال: اتفقوا معه على قواعد واضحة، كألا يبقى الجوال في غرفة النوم ليلاً، وبيّنوا له السبب.","الصحبة: «المرء على دين خليله، فلينظر أحدكم من يخالل» (رواه أبو داود والترمذي، وحسّنه).","خذوا علامات الاكتئاب والقلق عند المراهق بجدّية: العزلة، أو تغيّر النوم والأكل، أو الحديث عن الموت، واطلبوا مساعدة مختص فوراً.","أعطوه مسؤولية حقيقية، كمصروف شهري يديره بنفسه."],"boys":["وجّهوا رغبته في إثبات رجولته إلى العمل النافع والتطوع والرياضة.","حذّروه من التدخين والمخدرات بالمعلومة، لا بالتخويف وحده.","علّموه مسؤوليته القادمة: النفقة، وأن القوامة رعاية لا سيطرة."],"girls":["كوني أول من تلجأ إليه إذا ضايقها أحد أو ابتزّها عبر الإنترنت، دون لوم.","علّميها قيمتها عند الله، حتى لا تبحث عنها في إعجاب الناس.","حدّثيها عن الحب والمشاعر بصراحة، وأن الطريق الحلال هو الذي يحفظها."]},{"id":"uni","name":"الجامعة","age":"من ثماني عشرة إلى اثنتين وعشرين سنة","role":"دورك: المشورة والدعم دون تحكّم","common":["ساعدوه على اختيار تخصصه بحسب قدراته وميوله، لا بحسب كلام الناس.","ثقوا به وامنحوه مساحة، مع البقاء قريبين منه.","شجّعوه على تعلّم مهارة أو حرفة مع الدراسة.","ذكّروه بالغاية: العلم النافع عبادة: «من سلك طريقًا يلتمس فيه علمًا سهّل الله له به طريقًا إلى الجنة» (رواه مسلم)."],"boys":["مهّدوا له لفكرة الادخار للزواج والاستقلال.","أوصوه بالمحافظة على الصلاة في الجامعة."],"girls":["تعليم البنت حقها، وقد كانت الصحابيات والتابعيات عالمات وفقيهات.","علّموها ضوابط التعامل مع زملائها باحترام ووضوح وحدود.","إن سافرت أو سكنت سكناً جامعياً، فاتفقوا معها على تواصل يومي وأمان."]},{"id":"work","name":"التخرج والعمل","age":"بعد الجامعة","role":"دورك: الدعاء والتشجيع","common":["الكسب الحلال عبادة: «ما أكل أحد طعامًا قط خيرًا من أن يأكل من عمل يده» (رواه البخاري).","صبّروه في فترة البحث عن عمل، ولا تقارنوه بغيره.","علّموه أن يتصدق من أول راتب."],"boys":["هذه مرحلة المسؤولية، فساعدوه على بناء نفسه دون استعجاله إلى الزواج قبل القدرة."],"girls":["عملها جائز بضوابطه، وراتبها ملكها، ولا يلزمها الإنفاق على البيت إلا برضاها.","ساعدوها على التوازن بين طموحها ودورها القادم زوجةً وأماً."]},{"id":"marriage","name":"زواج الأبناء","age":"","role":"دورك: النصيحة ثم الانسحاب بلطف","common":["معيار الاختيار الدين والخلق: «إذا جاءكم من ترضون دينه وخلقه فزوّجوه» (رواه الترمذي وحسّنه)، و«تُنكح المرأة لأربع... فاظفر بذات الدين تربت يداك» (متفق عليه).","يسّروا الزواج ولا تعسّروه بالمغالاة في الجهاز والمهر والطلبات.","الاستخارة والاستشارة قبل القرار.","بعد الزواج: بيت الابن أو البنت مملكتهما، فانصحوا إن طلبا، ولا تتدخلوا في التفاصيل."],"boys":["لا تختاروا له، بل ساعدوه على الاختيار.","عاملوا زوجته معاملة البنت، فهي التي ستربي أحفادكم، وإن وقع خلاف فأنصفوها ولو على ابنكم.","ذكّروه: «خيركم خيركم لأهله» (رواه الترمذي وصححه)."],"girls":["لا تُزوَّج إلا برضاها: «لا تُنكح الأيم حتى تُستأمر، ولا البكر حتى تُستأذن» (متفق عليه).","علّموها حقوقها وواجباتها، وأن البيت يُبنى بالصبر والتفاهم.","كونوا ملجأها الآمن، دون تحريضها على زوجها.","من حقها أن تشترط شروطاً معقولة في العقد: «أحق الشروط أن توفوا به ما استحللتم به الفروج» (متفق عليه)."]},{"id":"grand","name":"الأحفاد","age":"","role":"دورك: الحنان والحكمة والدعم","common":["أنتم مصدر الحكايات والقيم والحنان.","احترموا طريقة الوالدين في التربية، ولا تنقضوا كلمتهما أمام الأولاد.","ساعدوا دون أن تحمّلوا أنفسكم فوق الطاقة، فصحتكم أمانة.","احكوا لهم قصص الأنبياء والصحابة والصحابيات."],"boys":[],"girls":[]}],"birr":{"life":["﴿وقضى ربك ألا تعبدوا إلا إياه وبالوالدين إحسانًا إما يبلغن عندك الكبر أحدهما أو كلاهما فلا تقل لهما أف ولا تنهرهما وقل لهما قولًا كريمًا﴾ (الإسراء: 23).","سُئل النبي ﷺ: من أحق الناس بحسن صحابتي؟ قال: «أمك»، قال: ثم من؟ قال: «أمك»، قال: ثم من؟ قال: «أمك»، قال: ثم من؟ قال: «أبوك» (متفق عليه).","علّموا أولادكم البرّ ببرّكم لوالديكم أمامهم، فهم يتعلمون بالقدوة.","يكون البرّ بالكلمة الطيبة، والزيارة، والاتصال، والنفقة إن احتاجا، وقضاء حوائجهما، والدعاء."],"after":[{"t":"الدعاء والاستغفار","d":"«إذا مات الإنسان انقطع عنه عمله إلا من ثلاثة: صدقة جارية، أو علم يُنتفع به، أو ولد صالح يدعو له» (رواه مسلم). و«إن الرجل لتُرفع درجته في الجنة، فيقول: أنّى لي هذا؟ فيُقال: باستغفار ولدك لك» (رواه ابن ماجه، وحسّنه الألباني)."},{"t":"الصدقة عنهم","d":"قال رجل: إن أمي افتُلتت نفسها، وأظنها لو تكلمت تصدقت، فهل لها أجر إن تصدقت عنها؟ قال: «نعم» (متفق عليه). وأفضلها: سقي الماء، وبناء مسجد، وطباعة مصحف، وكفالة يتيم."},{"t":"قضاء ديونهم","d":"«نفس المؤمن معلّقة بدَينه حتى يُقضى عنه» (رواه الترمذي وحسّنه). فأول ما يُبدأ به في التركة بعد التجهيز سداد الديون."},{"t":"الحج والعمرة عنهم","d":"جاءت امرأة فقالت: إن أمي نذرت أن تحج فلم تحج حتى ماتت، أفأحج عنها؟ قال: «نعم، حجي عنها» (رواه البخاري). بشرط أن يكون من يحج عنهم قد حج عن نفسه أولاً."},{"t":"الصيام عنهم","d":"«من مات وعليه صيام صام عنه وليه» (متفق عليه). وخص بعض العلماء ذلك بصيام النذر، وأجازه آخرون في القضاء."},{"t":"تنفيذ وصيتهم","d":"نفّذوا وصيتهم في حدود الثلث ولغير وارث: «الثلث، والثلث كثير» (متفق عليه)، و«لا وصية لوارث» (رواه أبو داود والترمذي وصححه)."},{"t":"صلة أحبابهم وأصدقائهم","d":"«إن أبرّ البر صلة الولد أهل ود أبيه» (رواه مسلم). وكان النبي ﷺ يكرم صديقات خديجة بعد موتها."},{"t":"العدل في الميراث","d":"قسمة التركة كما أمر الله، وحرمان البنات أو الأخوات من حقهن محرّم وظلم عظيم، وهو للأسف منتشر."}],"forYou":["اكتب وصيتك، وما لك من ديون وما عليك، من الآن.","ابدأ صدقة جارية في حياتك ولو صغيرة.","ربِّ أولادك على الدعاء لك، فهو أعظم ميراث.","اعدل بين أولادك في الهبات في حياتك، ولا تكتب أملاكاً لأحدهم لتحرم غيره."]},"inheritance":{"intro":"تولّى الله قسمة الميراث بنفسه في القرآن، وختم آياته بقوله: ﴿تلك حدود الله ومن يطع الله ورسوله يدخله جنات﴾ (النساء: 13). والتفاصيل هنا مبسطة للحالات الشائعة، أما الحالات المعقدة فتلزمها حصر الورثة من المحكمة وسؤال متخصص في المواريث.","order":["تجهيز الميت ودفنه من ماله.","سداد الديون، ومنها مؤخر صداق الزوجة إن لم يُدفع.","تنفيذ الوصية في حدود الثلث ولغير وارث.","قسمة الباقي على الورثة بحسب الفروض."],"shares":[{"who":"الزوج","rule":"النصف إن لم يكن لزوجته ولد، والربع إن كان لها ولد منه أو من غيره."},{"who":"الزوجة","rule":"الربع إن لم يكن لزوجها ولد، والثمن إن كان له ولد، وإن تعددت الزوجات اشتركن في هذا النصيب."},{"who":"البنت","rule":"إن انفردت ولا ابن معها فلها النصف، وللبنتين فأكثر الثلثان، وإن كان معهن ابن فالباقي بينهم للذكر مثل حظ الأنثيين."},{"who":"الابن","rule":"عَصَبة، يأخذ الباقي بعد أصحاب الفروض، وإن كان معه بنات فللذكر مثل حظ الأنثيين."},{"who":"الأب","rule":"السدس مع الابن، والسدس والباقي مع البنات فقط، والباقي كله إن لم يكن للميت ولد."},{"who":"الأم","rule":"السدس مع الولد أو مع اثنين فأكثر من الإخوة، والثلث في غير ذلك، وفي مسألة الزوج أو الزوجة مع الأبوين فقط تأخذ ثلث الباقي."},{"who":"الإخوة","rule":"يرثون عند عدم الابن والأب، وتفاصيلهم كثيرة، فاسأل متخصصاً."}],"doubts":["لماذا للولد ضعف البنت؟ هذا في حالات محددة فقط، والسبب أن الرجل مكلّف بالمهر والنفقة على نفسه وزوجته وأولاده وأحياناً أخواته، والبنت نصيبها لها وحدها لا يلزمها الإنفاق منه على أحد.","وجد العلماء الذين استقرؤوا الحالات أن المرأة ترث نصف الرجل في حالات قليلة، ومثله أو أكثر منه في حالات أكثر بكثير، ومنها حالات ترث فيها ولا يرث هو.","الأب والأم مع وجود الابن يأخذان النصيب نفسه: السدس لكل منهما."]},"program":[{"id":"0-2","ic":"👶","name":"من الولادة إلى سنتين","daily":["الأذان والتحنيك والتسمية الحسنة والعقيقة في السابع.","الرضاعة بحنان، والكلام مع الرضيع كثيراً، فالكلام يبني لغته وعقله.","أسمِعه القرآن والأذكار يومياً بصوتك."],"weekly":["قبّله واحمله وابتسم له كل يوم، فالأمان أساس كل ما بعده.","روتين نوم ثابت مع أذكار النوم بصوت هادئ.","لا شاشات قبل سنتين."],"goals":["يشعر بالأمان والحب.","يتعرّف على أصوات القرآن والأذكار."]},{"id":"3-6","ic":"🧒","name":"من ٣ إلى ٦ سنوات","daily":["حفّظه الفاتحة وقصار السور، وآية كل أسبوع.","علّمه أذكار اليوم: الطعام، والنوم، والخروج، ودخول الخلاء.","قصة قبل النوم من قصص الأنبياء (قسم «الحكايات»).","لعب حر يومي، ولعب مشترك معك ربع ساعة على الأقل."],"weekly":["يصلي بجانبك بعض الصلوات تقليداً لا إلزاماً.","تعليم الأدب بالقدوة: السلام، والشكر، والاعتذار، والاستئذان.","علّمه خصوصية جسده بلطف.","مسؤولية صغيرة: يرتب ألعابه، ويساعد في المائدة."],"goals":["يحفظ قصار السور وأذكار اليوم.","يحب الله ورسوله ﷺ.","يعرف آداب الطعام والسلام."]},{"id":"7-9","ic":"📚","name":"من ٧ إلى ٩ سنوات","daily":["الصلاة: تدريب يومي بالتشجيع وجدول نجوم، والذهاب للمسجد مع الأب.","حفظ القرآن بخطة ثابتة (مثلاً ٥ أسطر يومياً مع مراجعة).","وقت دراسة ثابت، ووقت لعب ورياضة ثابت."],"weekly":["جلسة عائلية أسبوعية: قصة صحابي أو آية وتدبرها.","صيام بعض الأيام في رمضان تدريباً.","مصروف صغير يتعلم به الادخار والصدقة.","تعرّف على أصدقائه وأهلهم."],"goals":["يصلي الخمس معظم الأيام.","يقرأ القرآن من المصحف.","يعرف الصدق والأمانة ويطبقهما."]},{"id":"10-12","ic":"🕌","name":"من ١٠ إلى ١٢ سنة","daily":["الصلاة بحزم ومتابعة، والجماعة للأولاد.","التفريق في المضاجع.","التمهيد للبلوغ بالمعلومة الصحيحة الهادئة (للبنت من الأم، وللولد من الأب)."],"weekly":["صيام رمضان كاملاً إن أطاق.","مشروع صغير أو مهارة: لغة، أو برمجة، أو حرفة، أو رياضة منتظمة.","قواعد واضحة للجوال والإنترنت مع رقابة وحوار.","حوار أسبوعي منفرد: «ماذا أعجبك هذا الأسبوع؟ وماذا ضايقك؟»"],"goals":["يعرف أحكام الطهارة والصلاة والصيام.","عنده صديق صالح على الأقل.","يتحمل مسؤولية دراسته."]},{"id":"13-17","ic":"🧑","name":"من ١٣ إلى ١٧ سنة","daily":["الصحبة بدل الأوامر: استمع أكثر مما تتكلم.","احترم خصوصيته مع متابعة غير مباشرة.","شجّعه على الفجر في المسجد وورد يومي يختاره بنفسه."],"weekly":["أعطه مسؤوليات حقيقية في البيت والمال.","ناقش معه الشبهات والأسئلة الكبرى بلا غضب (قسم «رفيق» و«رفيقة»).","تطوع أسبوعي أو عمل خير.","علّمه ضوابط التعامل مع الجنس الآخر، والعفة، وخطر الإباحية (بحوار هادئ)."],"goals":["يملك هدفاً واضحاً لدينه ودراسته.","يستطيع أن يقول «لا» للخطأ أمام أصحابه.","يثق بوالديه ويرجع إليهما."]}],"mistakes":[{"t":"المقارنة بين الأولاد أو بغيرهم","d":"تزرع الحسد والشعور بالنقص، والعدل مأمور به حتى في المشاعر الظاهرة.","ev":[{"t":"«فاتقوا الله واعدلوا بين أولادكم»","ref":"متفق عليه","id":"bukhari:2587"}],"sci":"المقارنة تجعل الطفل يقيس قيمته بغيره لا بجهده، فتضعف ثقته بنفسه وتزيد الغيرة والعداوة بين الإخوة. وتشير أبحاث علم نفس النمو إلى أن شعور الطفل بأن أحد إخوته مفضَّل عليه يرتبط بزيادة المشكلات السلوكية والقلق، حتى لو كانت المعاملة الفعلية متقاربة.","steps":["قارن الطفل بنفسه فقط: «أنت اليوم أفضل من الأسبوع الماضي».","امدح الجهد والسلوك المحدد لا الذكاء والشكل: «رتّبت كتبك وحدك، أحسنت».","اكتشف ميزة خاصة لكل ولد وسمّها له.","خصّص لكل ولد ١٠–١٥ دقيقة يومياً معك وحده.","لا تمدح أحدهم أمام الآخر بقصد تحفيز الثاني."],"say":[["لماذا لست مثل أخيك؟","أنا واثق أنك تقدر، تعال نحاول خطوة خطوة"],["ابن خالتك حصل على الدرجة الكاملة","ما الذي صعب عليك؟ كيف أساعدك؟"]]},{"t":"الدعاء على الأولاد عند الغضب","d":"قد توافق ساعة إجابة فيندم الوالد.","ev":[{"t":"«لا تدعوا على أنفسكم، ولا تدعوا على أولادكم، ولا تدعوا على أموالكم، لا توافقوا من الله ساعة يُسأل فيها عطاء فيستجيب لكم»","ref":"رواه مسلم","id":"muslim:7512"}],"sci":"الكلمة القاسية في لحظة الغضب تُحفر في ذاكرة الطفل أكثر من عشرات الكلمات الطيبة؛ فالدماغ يتذكر التجارب المؤلمة بقوة أكبر (ما يسميه الباحثون «تحيز السلبية»). والطفل الذي يسمع الدعاء عليه يفهم أن حب والديه مشروط ومهدَّد.","steps":["اتفق مع نفسك مسبقاً على جملة بديلة تقولها عند الغضب، مثل: «اللهم أصلحه».","إذا شعرت بالغضب: اسكت، وغيّر مكانك أو هيئتك، وتوضأ؛ فهذا هدي نبوي ويوقف تصاعد الانفعال.","أجّل الحديث في الخطأ حتى تهدأ.","إن زلّ لسانك فاعتذر لطفلك وادعُ له أمامه."],"say":[["الله ياخدك / الله لا يوفقك","الله يهديك ويصلحك، أنا زعلان من تصرفك لا منك"]]},{"t":"الكذب على الطفل لتسكيته","d":"يعلّمه الكذب ويهدم ثقته بوالديه.","ev":[{"t":"«أما إنك لو لم تعطيه شيئاً كُتبت عليك كذبة»","ref":"رواه أبو داود","id":"abudawud:4991"}],"sci":"الطفل يتعلم الصدق من التجربة لا من النصيحة. وقد وجدت دراسات على الأطفال أن الطفل الذي كذب عليه الكبار كان أكثر ميلاً للغش والكذب بعدها، لأنه يتعلم أن الكذب وسيلة مقبولة. كما أن الوعود الكاذبة تهدم ثقته بكلام والديه، فلا يصدقهم حين يجدّون.","steps":["لا تعد إلا بما ستفعله، وإن تعذّر الوفاء فاعتذر واشرح السبب.","قل الحقيقة بلغة بسيطة تناسب عمره: «سأذهب للعمل وأرجع بعد العصر».","لا تخوّفه بأشياء غير حقيقية (الغول، الشرطي، الإبرة) لتسكيته.","عند الطبيب: «الإبرة توجع قليلاً ثم تخف، وأنا معك»."],"say":[["إذا سكتّ أشتري لك لعبة (ولا تشتري)","أعرف أنك متضايق، سنخرج بعد أن ننتهي هنا"],["الدواء حلو","طعمه مر قليلاً، لكنه سيساعدك أن تتحسن"]]},{"t":"القسوة والعنف وكثرة الصراخ","d":"تولّد الخوف والكذب والعناد، والرفق يزيّن كل شيء.","ev":[{"t":"«إن الرفق لا يكون في شيء إلا زانه، ولا يُنزع من شيء إلا شانه»","ref":"رواه مسلم","id":"muslim:6602"}],"sci":"الصراخ المستمر يضع الطفل في حالة توتر دائم، فيرتفع هرمون الكورتيزول ويضعف التركيز والتعلم. ووجدت دراسة منشورة في مجلة Child Development (٢٠١٤) أن التأديب اللفظي القاسي (الصراخ والشتم) في سن المراهقة ارتبط بزيادة الاكتئاب والمشكلات السلوكية، حتى مع وجود علاقة دافئة في أوقات أخرى. ومع كثرة الصراخ يتعوّد الطفل عليه فلا يستجيب إلا له.","steps":["انزل لمستوى عين الطفل، وتكلم بصوت هادئ منخفض؛ الهدوء يجذب الانتباه أكثر.","أعط الأمر مرة واحدة بوضوح، ثم نفّذ عاقبة منطقية متفقاً عليها مسبقاً.","ضع قواعد قليلة واضحة للبيت (٣–٥ قواعد) وعلّقها.","لاحظ السلوك الحسن وامدحه فوراً؛ الانتباه للحسن يقلل السيئ.","إن صرخت فاعتذر: «آسف أني رفعت صوتي، كان المفروض أتكلم بهدوء»."],"say":[["كم مرة أقول لك! (بصراخ)","انظر إليّ… الآن وقت ترتيب الألعاب، بعدها نقرأ القصة"]]},{"t":"ضرب الوجه أو الإهانة","d":"الوجه محترم، والإهانة تكسر النفس.","ev":[{"t":"«إذا قاتل أحدكم أخاه فليجتنب الوجه»","ref":"رواه مسلم","id":"muslim:6651"}],"sci":"خلصت مراجعة علمية واسعة شملت نحو ١٦٠ ألف طفل (Gershoff وGrogan-Kaylor، ٢٠١٦) إلى أن الضرب يرتبط بزيادة العدوانية والمشكلات النفسية وضعف العلاقة بالوالدين، ولا يحسّن الطاعة على المدى البعيد. والإهانة أمام الآخرين تهدم احترام الطفل لذاته، فيتعلم إما الخضوع والخوف أو التمرد.","steps":["استبدل العقاب البدني بعواقب منطقية مرتبطة بالخطأ: كسر لعبة أخيه ← يعطيه من لعبه أو يصلحها.","الحرمان المؤقت من امتياز (الجهاز، الخروج) بمدة قصيرة واضحة.","وقت الهدوء: يجلس في مكان هادئ دقائق بعدد سنوات عمره، ثم تتحاوران.","انصح سراً، وامدح علناً.","لا تضرب وجهاً أبداً، ولا تعاقب وأنت غاضب."],"say":[["أنت غبي / فاشل","هذا التصرف خطأ، وأنت ولد طيب تقدر تصلحه"]]},{"t":"الأمر بما لا يفعله الوالدان","d":"الطفل يقلّد ما يرى، فالتناقض يُفقد الكلام أثره.","ev":[{"t":"﴿كبر مقتًا عند الله أن تقولوا ما لا تفعلون﴾","ref":"61:3","id":"quran:61:3"}],"sci":"يتعلم الطفل بالملاحظة والتقليد قبل التعليم المباشر، وهو ما أثبتته تجارب «التعلم بالملاحظة» الشهيرة لعالم النفس ألبرت باندورا. فإذا تعارض القول مع الفعل صدّق الطفل الفعل. والوالد الذي ينهى عن الجوال وهو ممسك به يعلّم ابنه أن القواعد للصغار فقط.","steps":["اختر عادة واحدة تريدها في ولدك وطبّقها أنت أولاً هذا الشهر.","دعه يراك تصلي وتقرأ القرآن وتعتذر وتشكر.","اجعل القواعد عامة على الجميع: «في بيتنا لا جوال على الطعام» تشمل الأب والأم.","إن أخطأت أمامه فاعترف: «أنا أخطأت، والصواب كذا»."],"say":[["لا تمسك الجوال (وأنت ممسك به)","تعال نضع جوالاتنا كلنا في السلة وقت الأكل"]]},{"t":"ترك الأولاد للشاشات والشارع بلا متابعة","d":"الراعي مسؤول عن رعيته، والإهمال تضييع للأمانة.","ev":[{"t":"«كفى بالمرء إثماً أن يضيّع من يقوت»","ref":"رواه أبو داود","id":"abudawud:1692"}],"sci":"توصي الأكاديمية الأمريكية لطب الأطفال بتجنب الشاشات قبل ١٨–٢٤ شهراً إلا مكالمات الفيديو، وبحد ساعة يومياً من المحتوى الجيد بين سنتين وخمس سنوات مع مشاركة الوالدين. وكثرة الشاشات ترتبط بتأخر الكلام، وضعف الانتباه، وقلة النوم، والسمنة. والطفل بلا متابعة معرّض لمحتوى ضار ولأشخاص مجهولين عبر الألعاب والتطبيقات.","steps":["ضعوا «خطة شاشات» عائلية مكتوبة: متى، وكم، وأين، وماذا.","الأجهزة في مكان مشترك في البيت، ولا أجهزة في غرف النوم ليلاً.","فعّل الرقابة الأبوية (Google Family Link أو Screen Time) وراجع التطبيقات والأصدقاء في الألعاب.","لا شاشات قبل النوم بساعة، ولا أثناء الطعام.","وفّر البدائل: رياضة، ولعب حركي، وقراءة، وزيارة أقارب، ونشاط مشترك أسبوعي.","اعرف أصحاب ولدك وأين يلعب، واتفق معه على أوقات الرجوع.","علّمه: لا يعطي معلوماته أو صوره لأحد، ويخبرك فوراً إذا طلب منه أحد سراً أو صورة."],"say":[["خذ الجوال واسكت","نلعب مع بعض ٢٠ دقيقة، ثم لك نصف ساعة على الجهاز"]]},{"t":"حرمان الطفل من الحنان باسم الرجولة أو الحزم","d":"كان النبي ﷺ يقبّل الحسن والحسين ويحملهما.","ev":[{"t":"«من لا يَرحم لا يُرحم»","ref":"متفق عليه","id":"bukhari:5997"}],"sci":"بيّنت أبحاث «نظرية التعلق» (بولبي وأينسورث) أن الطفل الذي يشعر بالأمان العاطفي مع والديه يكون أكثر جرأة واستقلالاً وثقة، لا أكثر دلالاً. والحرمان من الحنان يرتبط بصعوبة التعبير عن المشاعر، والقلق، والبحث عن الاهتمام خارج البيت. واللمس والضم يخفضان التوتر عند الطفل.","steps":["ضمّة وقبلة يومية لكل ولد، بنتاً كان أو ولداً، صغيراً أو مراهقاً.","قل «أحبك» صريحة، ولا تكتفِ بأن «يعرف ذلك».","سمِّ مشاعره ولا تنكرها: «أعرف أنك حزين».","الحزم في القواعد والحنان في الأسلوب يجتمعان: «لن تخرج الآن، وأنا أفهم أنك متضايق»."],"say":[["لا تبكِ، أنت رجل","البكاء ليس عيباً، احكِ لي ما الذي أحزنك"]]},{"t":"تأجيل التربية الدينية إلى الكبر","d":"الصغر زمن الغرس، والعادة في الصغر تثبت في الكبر.","ev":[{"t":"«مُروا أولادكم بالصلاة وهم أبناء سبع سنين...»","ref":"رواه أبو داود","id":"abudawud:495"}],"sci":"السنوات الأولى (حتى السابعة تقريباً) هي فترة أسرع نمو للدماغ وتكوين العادات، وما يُكتسب فيها بالتكرار والمحبة يصبح جزءاً من هوية الطفل. أما بعد المراهقة فيصبح تغيير العادة أصعب، ويحتاج الأمر إلى إقناع لا إلى تعويد.","steps":["ابدأ بالمحبة: عرّفه بالله من خلال نعمه قبل الأوامر.","اربط العبادة بالفرح: سجادة خاصة، ومكافأة على المواظبة، ونزهة بعد صلاة الجمعة.","روتين يومي قصير: ذكر الصباح في السيارة، وسورة قبل النوم، وقصة نبي أسبوعياً.","من السابعة: جدول صلاة بالنجوم، ومن العاشرة: حزم مع حوار.","استعن بقسم «زاد البراعم» في التطبيق."],"say":[["لما تكبر تصلي","تعال نصلي مع بعض، وأنت تقف بجانبي مثل الكبار"]]},{"t":"التفرقة بين الذكر والأنثى في المعاملة والعطاء","d":"من أخلاق الجاهلية، وللبنات فضل عظيم في التربية.","ev":[{"t":"«من عال جاريتين حتى تبلغا جاء يوم القيامة أنا وهو» وضمّ أصابعه","ref":"رواه مسلم","id":"muslim:6695"}],"sci":"التفرقة تولّد شعوراً بالظلم والغيرة، وتؤثر في تقدير البنت لذاتها وفي علاقة الإخوة ببعضهم حتى بعد الكبر. ودراسات الأسرة تربط المعاملة غير المتساوية بين الإخوة بانخفاض الرضا عن النفس والاكتئاب لدى الطرف الأقل حظاً.","steps":["اعدل في الهدايا والمصروف والوقت والمدح بين الأولاد والبنات.","اعطِ كل واحد مسؤوليات في البيت بحسب عمره لا بحسب جنسه وحده.","لا تجعل الأخ وصياً على أخته بالقسوة، بل علّمه أن يكون سنداً وحامياً لها.","استمع لرأي البنت كما تستمع لرأي الولد.","في العطايا المالية الكبيرة استشر أهل العلم في كيفية العدل."],"say":[["أنتِ بنت، اتركي أخاك يقرر","رأيك مهم، تعالوا نسمع رأي الاثنين"]]},{"t":"الحماية الزائدة والقيام بكل شيء عن الطفل","d":"خوف الوالدين يمنع الطفل من التجربة والخطأ.","sci":"الطفل يبني ثقته ومهاراته من التجارب التي ينجح فيها بنفسه، والحماية الزائدة ترتبط بالقلق وضعف الاعتماد على النفس.","steps":["اسمح بالمخاطر الصغيرة الآمنة: يتسلق، يطبخ مع إشرافك.","لا تحل مشكلاته مع أصدقائه بدلاً منه؛ علّمه كيف يحلها.","مهام منزلية تناسب عمره.","ذكّر نفسك: هدف التربية أن يستغني عنك يوماً."],"say":[["اتركه، أنا أسويه عنك","جرّب، وإذا احتجت أنا قريب"]]},{"t":"التهديد بما لا يُنفَّذ","d":"تهديدات كثيرة لا تُطبّق: «سأتركك هنا»، «لن تخرج أبداً».","sci":"التهديد غير المنفّذ يعلّم الطفل أن كلام والديه لا قيمة له، والتهديد المخيف يزرع القلق.","steps":["لا تذكر عاقبة إلا إذا كنت ستنفذها فعلاً.","اجعل العاقبة قصيرة ومعقولة ومرتبطة بالخطأ.","نفّذ بهدوء وبلا محاضرة."],"say":[["سأتركك في السوق!","إذا ركضت مرة ثانية نرجع للسيارة"]]},{"t":"العقاب بالحرمان من الطعام أو النوم","d":"حرمان الطفل من وجبة أو إرساله للنوم جائعاً.","sci":"الحاجات الأساسية ليست ورقة ضغط؛ ربطها بالعقاب يضر بالصحة وبعلاقة الطفل بالطعام والنوم.","steps":["استخدم عواقب منطقية بدلاً منها.","لا تجعل الحلوى مكافأة ولا الطعام عقاباً."],"say":[]},{"t":"الانشغال الدائم بالجوال أمام الأطفال","d":"الوالد حاضر بجسده غائب بعقله.","sci":"تشير دراسات إلى أن انشغال الوالدين بالأجهزة أثناء التفاعل مع الطفل يقلل التواصل ويرتبط بزيادة سلوكيات طلب الانتباه.","steps":["أوقات بلا أجهزة: الوجبات، وأول ساعة بعد العودة، وقبل النوم.","إن احتجت الجوال اشرح له: «أرد على رسالة عمل دقيقتين».","نشاط أسبوعي مشترك بلا شاشات."],"say":[["(تهزّ رأسك وأنت تقرأ الجوال)","لحظة أضع الجوال… الآن احكِ لي"]]},{"t":"عدم الاتفاق بين الأب والأم أمام الأطفال","d":"الأب يسمح والأم تمنع، أو العكس.","sci":"التناقض يربك الطفل ويعلمه أن يستغل الطرف الأسهل، ويضعف سلطة الوالدين معاً.","steps":["اتفقا على القواعد الأساسية مسبقاً.","الخلاف يناقش بعيداً عن الأطفال.","لا تنقض قرار الآخر أمامهم.","قل: «سأتكلم مع أمك/أبيك ونرد عليك»."],"say":[]},{"t":"الاستهزاء بمشاعر الطفل","d":"السخرية من خوفه أو بكائه أو اهتماماته.","sci":"إنكار مشاعر الطفل يعلمه أن يخفيها، فلا يأتي إليك حين يكون في خطر.","steps":["اعترف بالشعور قبل أي توجيه.","لا تحكِ مواقفه المحرجة أمام الآخرين.","احترم اهتماماته ولو بدت صغيرة."],"say":[["تخاف من هذا؟ هههه","أفهم أنك خايف، تعال نشوفه معاً"]]},{"t":"التدليل المفرط وتلبية كل الطلبات","d":"إعطاء الطفل كل ما يريد فوراً.","sci":"الطفل الذي لا يتعلم الانتظار والحرمان المؤقت يصعب عليه ضبط نفسه لاحقاً، وتجارب «تأجيل الإشباع» ترتبط مهارتها بنجاح أفضل.","steps":["دعه ينتظر ويدّخر لما يريد.","الهدايا في المناسبات لا يومياً.","المحبة بالوقت والاهتمام لا بالأشياء."],"say":[]},{"t":"كثرة الأوامر والتعليمات","d":"سيل من الأوامر طوال اليوم: «افعل… لا تفعل».","sci":"مع كثرة الأوامر يتوقف الطفل عن الاستماع، كما يتجاهل الإنسان الضجيج المستمر.","steps":["قلّل الأوامر إلى الأهم.","أمر واحد واضح في كل مرة.","صِغ الأمر إيجابياً: «امشِ» بدل «لا تركض».","استخدم الروتين والجداول بدل التكرار."],"say":[]},{"t":"الوعظ الطويل بعد كل خطأ","d":"محاضرة طويلة كلما أخطأ.","sci":"الطفل يتوقف عن الاستماع بعد دقيقة أو اثنتين، وكثرة الوعظ تنفّر من الحق نفسه.","steps":["جملة أو اثنتان تكفي.","اسأل: «ما الذي كان يمكن أن تفعله بدلاً من ذلك؟».","كان النبي ﷺ يتخوّل أصحابه بالموعظة مخافة السآمة."],"say":[]},{"t":"إلقاء اللوم على الطفل في خلافات الكبار","d":"إشراكه في مشكلات الزوجين أو العائلة.","sci":"تحميل الطفل هموم الكبار يسرق طفولته ويشعره بالذنب والقلق.","steps":["لا تشكُ له من الطرف الآخر.","لا تطلب منه أن يختار بينكما.","طمئنه أن مشكلات الكبار يحلها الكبار."],"say":[]},{"t":"تجاهل السلوك الحسن والانتباه للسيئ فقط","d":"لا يسمع الطفل تعليقاً إلا حين يخطئ.","sci":"الطفل يحتاج إلى الانتباه، فإذا لم يحصل عليه بالسلوك الحسن طلبه بالسيئ.","steps":["«امسكه وهو يُحسن»: امدح السلوك الحسن فوراً ومحدداً.","اجعل نسبة التعليقات الإيجابية أكثر بكثير من السلبية.","تجاهل السلوكيات المزعجة البسيطة غير الخطرة."],"say":[]},{"t":"عقاب الطفل وأنت غاضب","d":"العقوبة في لحظة الغضب.","sci":"العقاب في الغضب يكون غالباً أشد من الخطأ، ويتذكر الطفل غضبك لا الدرس.","steps":["أجّل القرار: «سنتكلم بعد أن أهدأ».","هدي الغضب: السكوت والوضوء وتغيير الهيئة.","لا يقضي القاضي وهو غضبان، فكيف بالوالد مع ولده."],"say":[]},{"t":"فرض المستقبل والتخصص على الأبناء","d":"اختيار التخصص والمهنة نيابة عنه.","sci":"الدافعية الداخلية أقوى أسباب النجاح، والإجبار يرتبط بضعف الإنجاز والندم.","steps":["ساعده في اكتشاف ميوله وقدراته.","قدّم المعلومات والخبرة، واترك له القرار في المباح.","شاوره: «أنت تعيش هذا المستقبل»."],"say":[]},{"t":"المقارنة بالآباء: «نحن في زماننا…»","d":"رفض الواقع الجديد ومقارنته بالماضي دائماً.","sci":"الطفل يعيش زماناً مختلفاً، وكثرة المقارنة بالماضي تجعله يشعر أن والديه لا يفهمانه.","steps":["افهم عالمه قبل أن تحكم عليه.","استخدم قصص الماضي للإلهام لا للتوبيخ.","فرّق بين الثوابت التي لا تتغير والوسائل التي تتغير بتغير الزمان."],"say":[]},{"t":"التفريط في متابعة الأصدقاء والصحبة","d":"لا يعرف الوالدان أصدقاء أبنائهم.","sci":"الأقران من أقوى المؤثرات في سلوك الطفل والمراهق.","steps":["اعرف أصدقاءه بالاسم وأهلهم.","اجعل بيتك مكاناً مرحّباً بأصدقائه.","«المرء على دين خليله»."],"say":[]},{"t":"ربط الحب بالدرجات والإنجاز","d":"المحبة والرضا مرتبطان بالنجاح فقط.","sci":"الطفل الذي يشعر أن حب والديه مشروط بالإنجاز يصبح قلقاً ويخاف الفشل.","steps":["أظهر حبك في الفشل كما في النجاح.","افصل بين تقييم العمل وقيمة الطفل.","«أحبك دائماً، وسنعمل على تحسين الدرجة معاً»."],"say":[]},{"t":"الضغط لتحفيظ القرآن بالقسوة","d":"الضرب والصراخ في حلقات التحفيظ في البيت.","sci":"ربط القرآن بالخوف والألم قد يورث نفوراً يدوم، بينما يرتبط الحفظ الثابت بالتكرار المحبب.","steps":["جلسات قصيرة محبّبة.","مكافآت وإنجازات مرئية.","افهموا المعاني معاً.","القدوة: يرى والديه يقرآن."],"say":[]},{"t":"إهمال الأب لدوره التربوي","d":"ترك التربية كلها للأم بحجة العمل.","sci":"تشير الأبحاث إلى أن مشاركة الأب في التربية ترتبط بتحصيل أفضل وسلوك أفضل وثقة أعلى لدى الأبناء والبنات.","steps":["وقت يومي ولو قصير مع كل ابن.","نشاط أسبوعي: صلاة الجمعة، رياضة، مشوار.","شارك في قرارات التربية والمدرسة.","«كلكم راعٍ وكلكم مسؤول عن رعيته»."],"say":[]},{"t":"عدم الاعتذار للطفل عند الخطأ","d":"الوالد لا يعترف بخطئه أبداً.","sci":"اعتذار الوالد يعلم الطفل الاعتذار والتواضع، ويصلح العلاقة بعد الخلاف.","steps":["اعتذر بوضوح: «آسف أني صرخت».","بيّن ما ستفعله المرة القادمة.","الاعتذار لا يُسقط هيبتك، بل يزيد احترامك."],"say":[]},{"t":"تخويف الطفل بالله وحده","d":"ربط الله بالعقاب فقط: «الله يحرقك».","sci":"البدء بالمحبة والرجاء يورث محبة الله وطاعته، والتخويف وحده قد يورث النفور.","steps":["عرّفه بنعم الله ورحمته أولاً.","ثم علّمه المراقبة برفق.","كان النبي ﷺ يبشّر وييسّر: «يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا»."],"say":[["الله يحرقك إذا كذبت","الله يحب الصادقين، والصدق يجعل قلبك مرتاحاً"]]}],"podcasts":[{"t":"استشارة مع سارة","by":"د. سارة العبدالكريم — دكتوراه في الطفولة المبكرة، شبكة مايكس (السعودية)","d":"استشارات تربوية عملية من أسئلة الأهالي: الغيرة، والعناد، والدراسة، والمراهقة. وبعض حلقاتها بالتعاون مع جمعيات أسرية سعودية مرخّصة.","href":"https://podcasts.apple.com/sa/podcast/%D8%A7%D8%B3%D8%AA%D8%B4%D8%A7%D8%B1%D8%A9-%D9%85%D8%B9-%D8%B3%D8%A7%D8%B1%D8%A9/id1449825757"},{"t":"بودكاست جمعية وئام","by":"جمعية وئام للخدمات الأسرية (جمعية سعودية مرخّصة)","d":"حلقات توعوية في العلاقات الأسرية والتربية من مختصين.","href":"https://podcasts.apple.com/sa/podcast/%D8%AC%D9%85%D8%B9%D9%8A%D8%A9-%D9%88%D8%A6%D8%A7%D9%85/id1538545374"},{"t":"🇪🇬 خط نجدة الطفل ١٦٠٠٠ (مصر)","by":"المجلس القومي للطفولة والأمومة — جهة حكومية مصرية","d":"استشارات نفسية وقانونية مجانية للأسر، وبلاغات حماية الطفل، على مدار ٢٤ ساعة. واتساب: ٠١١٠٢١٢١٦٠٠.","href":"tel:16000"},{"t":"🇪🇬 نجدة الطفل على واتساب","by":"المجلس القومي للطفولة والأمومة","d":"التواصل كتابةً على الرقم ٠١١٠٢١٢١٦٠٠.","href":"https://wa.me/201102121600"},{"t":"جمعية المودة للتنمية الأسرية","by":"جمعية سعودية مرخّصة","d":"برامج واستشارات أسرية ومحتوى توعوي للوالدين.","href":"https://almawaddah.org.sa/"}]};
